/* DAWAH X — ahmad, অধ্যায় 58 · খণ্ড 58 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][58]=[[11401,11401,"","আমরা ভালো হাত দেয়ার ভালো দ্বারা বিচার করার চেষ্টা করেছি কিন্তু মাদকটি বলেছে যে ঈশ্বর তার প্রার্থনা করেছেন আর তিনি হয়ত আত্মসমর্পণ করেছেন। আমি তোমার সাথে কিছু জিনিস পূরণ করতে পারি, আর এটা কাজ করে না, তোমাকে খুঁজে বের করো।","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ أَحَقُّ مَا قَالَ الْعَبْدُ وَكُلُّنَا لَكَ عَبْدٌ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏","","",""],[11402,11402,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং স্বর্গ - নির্বাচিতির জন্য আত্মসমর্পণ করবেন । তারা বলে যারা ঈশ্বরকে ভালবাসে তারা হলো প্রিয় এবং মিষ্টি।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُتَحَابِّينَ ‏ ‏لَتُرَى غُرَفُهُمْ فِي الْجَنَّةِ كَالْكَوْكَبِ الطَّالِعِ الشَّرْقِيِّ أَوْ الْغَرْبِيِّ فَيُقَالُ مَنْ هَؤُلَاءِ فَيُقَالُ هَؤُلَاءِ الْمُتَحَابُّونَ فِي اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[11403,11403,"","আমরা একটা বাসা সম্বন্ধে কথা বলেছিলাম, যিনি এক বড় স্টিমারের জন্ম দিয়েছিলেন, যিনি একটা হাত দিয়েছিলেন । আপনি তার প্রার্থনায় এবং রাজার হতাশার মধ্যে পার্থক্য দেখতে পান ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيُلْقِ الشَّكَّ وَلْيَبْنِ عَلَى الْيَقِينِ وَلْيُصَلِّ سَجْدَتَيْنِ فَإِنْ كَانَتْ خَمْسًا ‏ ‏شَفَعَ ‏ ‏بِهِمَا وَإِنْ كَانَ صَلَّى أَرْبَعًا كَانَتَا تَرْغِيمًا لِلشَّيْطَانِ ‏","","",""],[11404,11404,"","আমি আমার ছেলের সঙ্গে একজন বয়স্ক দাস থাকার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا لَا يَمْنَعَنَّ أَحَدَكُمْ مَخَافَةُ النَّاسِ أَنْ يَقُولَ الْحَقَّ إِذَا رَآهُ ‏","","",""],[11405,11405,"","আমরা শপথ নিয়ে কথা বলেছি আপনার কথা শোনার চেষ্টা করার ব্যাপারে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خُلَيْدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏ذُكِرَ الْمِسْكُ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَوَلَيْسَ مِنْ أَطْيَبِ الطِّيبِ ‏","","",""],[11406,11406,"","আমরা আমার বাবার ছেলেকে আমার সুখী বাবার জন্য লেখার রীতি নিয়ে কথা বলেছি, যে কিনা ঈশ্বরের কাছে যাবে। সে যা জানত, তা ঘৃণা করত।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ حَيَاءً مِنْ عَذْرَاءَ فِي ‏ ‏خِدْرِهَا ‏ ‏وَكَانَ إِذَا كَرِهَ شَيْئًا عَرَفْنَاهُ فِي وَجْهِهِ ‏","","",""],[11407,11407,"","আমরা ঈশ্বরের কাছে যে ফুলগুলো আছে তার কথা বলেছি, আমি বলেছি, লর্ডকে বলছি যে, আমরা যে ফুলগুলো পেয়েছি তা যেন আমরা ভয় পাই, ছেলে কখনো করেনি ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اسْتُخْلِفَ مِنْ خَلِيفَةٍ إِلَّا كَانَتْ لَهُ ‏ ‏بِطَانَتَانِ ‏ ‏بِطَانَةٌ ‏ ‏تَأْمُرُهُ بِالْخَيْرِ وَتَحُضُّهُ عَلَيْهِ ‏ ‏وَبِطَانَةٌ ‏ ‏تَأْمُرُهُ بِالشَّرِّ وَتَحُضُّهُ عَلَيْهِ فَالْمَعْصُومُ مَنْ ‏ ‏عَصَمَ ‏ ‏اللَّهُ ‏","","",""],[11408,11408,"","আমরা তোমার টাকাকে বলে দিয়েছি যে আমরা তোমার টাকা বাঁচাব, আমার বাবা তার কাছে প্রার্থনা করেছে ঈশ্বরের কাছে প্রার্থনা করার জন্য। তারা তোমাকে সাহায্য করবে। তারা তোমাকে বলবে, ঈশ্বর আমাদের কাছে তোমার জন্য প্রার্থনা করবে। আপনার লর্ডকে বলুন আমরা খুশি হব যদি আপনি দয়া করে বলেন আমরা চলে যাব না... ...আমি আপনাকে বলতে না দিয়ে, হয়তো আমরা আপনার চাইতে ভালো, আমরা আপনাকে অনুরোধের পরিবর্তে বরং দিতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَقُولُ لِأَهْلِ الْجَنَّةِ يَا أَهْلَ الْجَنَّةِ فَيَقُولُونَ لَبَّيْكَ رَبَّنَا وَسَعْدَيْكَ فَيَقُولُ هَلْ رَضِيتُمْ فَيَقُولُونَ وَمَا لَنَا لَا ‏ ‏نَرْضَى وَقَدْ أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنْ خَلْقِكَ فَيَقُولُ أَنَا أُعْطِيكُمْ أَفْضَلَ مِنْ ذَلِكَ قَالُوا يَا رَبَّنَا فَأَيُّ شَيْءٍ أَفْضَلُ مِنْ ذَلِكَ قَالَ أُحِلُّ عَلَيْكُمْ رِضْوَانِي فَلَا أَسْخَطُ بَعْدَهُ أَبَدًا ‏","","",""],[11409,11409,"","আমি যদি স্বর্গকে আমার ভালবাসার জন্য সাহায্য করতে চাই, তাহলে আমরা খুশি হব। আমার বাবা, সৃষ্টিকর্তাকে সবচেয়ে ভালো করে বলেন, তুমি তার ঠোঁট কেটে ফেলবে এমনকি তার মাথাকে চুষিয়ে দিয়ে আর যতক্ষণ না তুমি চলে যাও ততক্ষণ পর্যন্ত তার মুখ বন্ধ থাকে.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ أَبُو شُجَاعٍ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏أَبِي الْهَيْثَمِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ { ‏وَهُمْ فِيهَا ‏ ‏كَالِحُونَ ‏ } ‏قَالَ ‏ ‏تَشْوِيهِ النَّارُ ‏ ‏فَتَقَلَّصُ شَفَتُهُ الْعُلْيَا حَتَّى تَبْلُغَ وَسَطَ رَأْسِهِ ‏ ‏وَتَسْتَرْخِي شَفَتُهُ السُّفْلَى حَتَّى تَضْرِبَ سُرَّتَهُ ‏","","",""],[11410,11410,"","আমি বাবার ভালবাসা নিয়ে কথা বলেছি আমার বাবাকে যে ভালো কথা বলেছি তা বলার জন্য। আমি একজন ভালো বাবা। আমি তাকে বললাম যে সে ঈশ্বরের জন্য প্রার্থনা করছে এবং সে স্বপ্ন দেখছে। ঈশ্বরের অনুগ্রহে তিনি তাকে আদেশ দিয়েছেন আর তারপর একটা চোর দিয়েছেন আর বললেন সে এটা করেছে, সে নাকি তার মুখের সামনে ভেঙ্গে গেছে, তার সঠিক পা নয়।","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ يَعْنِي الزُّهْرِيَّ ‏ ‏أَخْبَرَنِي ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي حَائِطِ الْمَسْجِدِ فَتَنَاوَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَصَاةً ‏ ‏فَحَتَّهَا ‏ ‏ثُمَّ قَالَ ‏ ‏إِذَا ‏ ‏تَنَخَّمَ ‏ ‏أَحَدُكُمْ وَهُوَ ‏ ‏يُصَلِّي فَلَا ‏ ‏يَتَنَخَّمْ ‏ ‏قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[11411,11411,"","আমরা শুধু পলাতকের কথা বলেছি একটা ছেলেকে কথা বলেছি, আমি খণ্ডন করেছি। ভগবান কি বলতে চান ঈশ্বরের সর্বশ্রেষ্ঠ ঈশ্বর আছে? তার অর্থ আর তার আত্মা বলে যে নিরাপদ কোন এক সময়ে ঈশ্বর মানুষকে রক্ষা করবে এবং মানুষকে খারাপ বলবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏أَنَّهُ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ أَيُّ النَّاسِ أَفْضَلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤْمِنٌ يُجَاهِدُ فِي سَبِيلِ اللَّهِ بِنَفْسِهِ وَمَالِهِ فَقَالُوا ثُمَّ مَنْ قَالَ مُؤْمِنٌ فِي ‏ ‏شِعْبٍ ‏ ‏مِنْ ‏ ‏الشِّعَابِ ‏ ‏يَتَّقِي اللَّهَ وَيَدَعُ النَّاسَ مِنْ شَرِّهِ ‏","","",""],[11412,11412,"","আমরা ঈশ্বরের ভালোর কথা বলেছিলাম। আমরা বিশ্বাস করি তুমি চলে যাও আর বিদায় বলো, যাতে তুমি আমার সাথে কথা বলতে না পারো। ভাই, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমি যে কোন মানুষের কাছে আত্মসমর্পণ করব। আমি বরং দাঙ্গা সৃষ্টির কথা উল্লেখ করতাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنْبَأَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَيْرِيزٍ الْجُمَحِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ بَيْنَا هُوَ جَالِسٌ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نُصِيبُ ‏ ‏سَبْيًا ‏ ‏فَنُحِبُّ الْإِثْمَانَ فَكَيْفَ ‏ ‏تَرَى فِي ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّكُمْ لَتَفْعَلُونَ ذَلِكُمْ لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوا ذَلِكُمْ فَإِنَّهَا لَيْسَتْ نَسَمَةٌ كَتَبَ اللَّهُ أَنْ تَخْرُجَ إِلَّا هِيَ خَارِجَةٌ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَوْزاعِيِّ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ أَفْضَلُ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏شُعَيْبٍ ‏","","",""],[11413,11413,"","আমি ঈশ্বরের নাম নিয়ে কথা বলেছিলাম যখন আমার বাবা বলেছিলেন যে আমার হাতে ভালো সময় আছে। আমি আকাশ থেকে একজন মহিলাকে নিয়ে যাচ্ছি, আমি তাকে চালু করেছি, সে শপথ নিয়েছে যে সে ঈশ্বরের হৃদয়ের কথা বলছে যেন এক পাপীর কাছ থেকে কিছু কিছু বলি। আমি তোমাকে ভালবাসি যখন তুমি বলো আমি তোমাকে বলেছি, আমি তোমাকে বলেছি, আমি তোমাকে বলছি, ঈশ্বর আমার জন্য প্রার্থনা করেছেন, মানুষ আপনার কি কি হয়েছে সম্পর্কে কথা বলবে আর তারপর এটা হবে এমন একটা জিনিস যা তুমি বলেছিলে তার মধ্যে দিয়ে যেতে। আমি তার পতাকাও তুলেছি। আমি সুরের সুরের সাথে লড়াই করছি। কিন্তু ভাববাদী তার জন্য প্রার্থনা করেছেন এবং তিনি মানুষের সাথে কথা বলছেন। যখন সে তাকে দেখতে পায়, সে বললো, ঈশ্বরের ইচ্ছা আছে, আমরা তার হাতে শ্বাস নেই, তুমি এমনকি আমাকেও ছেড়েও দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي حُسَيْنٍ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَيْنَا أَعْرَابِيٌّ فِي بَعْضِ نَوَاحِي ‏ ‏الْمَدِينَةِ ‏ ‏فِي غَنَمٍ لَهُ عَدَا عَلَيْهِ الذِّئْبُ فَأَخَذَ شَاةً مِنْ غَنَمِهِ فَأَدْرَكَهُ الْأَعْرَابِيُّ فَاسْتَنْقَذَهَا مِنْهُ وَهَجْهَجَهُ فَعَانَدَهُ الذِّئْبُ يَمْشِي ثُمَّ ‏ ‏أَقْعَى ‏ ‏مُسْتَذْفِرًا ‏ ‏بِذَنَبِهِ يُخَاطِبُهُ فَقَالَ أَخَذْتَ رِزْقًا رَزَقَنِيهِ اللَّهُ قَالَ وَاعَجَبًا مِنْ ذِئْبٍ ‏ ‏مُقْعٍ ‏ ‏مُسْتَذْفِرٍ ‏ ‏بِذَنَبِهِ يُخَاطِبُنِي فَقَالَ وَاللَّهِ إِنَّكَ لَتَتْرُكُ أَعْجَبَ مِنْ ذَلِكَ قَالَ وَمَا أَعْجَبُ مِنْ ذَلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏النَّخْلَتَيْنِ ‏ ‏بَيْنَ ‏ ‏الْحَرَّتَيْنِ ‏ ‏يُحَدِّثُ النَّاسَ عَنْ نَبَإِ مَا قَدْ سَبَقَ وَمَا يَكُونُ بَعْدَ ‏ ‏ذَلِكَ قَالَ فَنَعَقَ الْأَعْرَابِيُّ بِغَنَمِهِ حَتَّى أَلْجَأَهَا إِلَى بَعْضِ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ مَشَى إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ضَرَبَ عَلَيْهِ بَابَهُ فَلَمَّا صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيْنَ الْأَعْرَابِيُّ صَاحِبُ الْغَنَمِ فَقَامَ الْأَعْرَابِيُّ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِّثْ النَّاسَ بِمَا سَمِعْتَ وَمَا رَأَيْتَ فَحَدَّثَ الْأَعْرَابِيُّ النَّاسَ بِمَا رَأَى مِنْ الذِّئْبِ وَسَمِعَ مِنْهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ صَدَقَ آيَاتٌ تَكُونُ قَبْلَ السَّاعَةِ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ أَحَدُكُمْ مِنْ أَهْلِهِ فَتُخْبِرَهُ نَعْلُهُ أَوْ سَوْطُهُ أَوْ عَصَاهُ بِمَا أَحْدَثَ أَهْلُهُ بَعْدَهُ ‏","","",""],[11414,11414,"","আমরা আমার বাবার এত ভাল হওয়ার কথা বলেছিলাম ক্ষমতা ত্যাগ করার চেয়ে। আমি ভেবেছিলাম, যদি মা এটা করতো, সে বলত, ঈশ্বর যদি বলতেন, তিনি যদি বলতেন, তিনি তাই করতেন। তিনি বলেছিলেন, তিনি যদি চাইতেন, তাহলে তিনি বলতেন যে, তিনি যদি বলতেন, তিনি বলতেন, “তাহলে তিনি নিশ্চয়ই বলতেন যে, তিনি অবশ্যই বলতেন যে, তিনি যদি বলতেন, তিনি বললেন । তিনি যদি চাইতেন, তাহলে তিনি বলতেন যে, তিনি যদি বলতেন, তিনি নিশ্চয়ই বলতেন, “তাহলে তিনি নিশ্চয়ই বলতেন যে, তিনি যদি করতেন, তাহলে তিনি নিশ্চয়ই বলতেন যে, তিনি থাকতে পারতেন । সে বললে, সে যদি বলত, সে বলবে, 'সে আমাকে বললে, 'সে বলেছে, 'সে বলেছে, 'সে যদি বলেছিল, তাহলে বলে দেবে। সে বলল, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, তোমাকে বলতে হবে যে, সে অবশ্যই বলেছে যে, সে অবশ্যই বলছে যে, সে অবশ্যই বলছে। সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, সে বলছে, সে বলছে, সে বলছে। সে বলেছে, তার বলার দরকার নেই। সে বলেছে, সে বলেছে, সে বলেছে, সে বলেছে, তুমি যদি চাও, তবে তুমি বলবে না। ঘোড়া বলে যে আমি হয়তো তাকে কিছু বলতে পারি। তুমি বললে তোমার শক্তি তোমাকে গুলি করবে এবং বলে দাও যে তুমি বলছো যে আমি মানুষের কাছে যাব না। আর ঈশ্বরের কাছে যাও, ঈশ্বর বলেছিলেন, \"উত্তর-পশ্চিমে তুমি মানুষ যেতে দেবে না যদি তারা জন্ম হয়।\" ঈশ্বর বলেছিলেন যদি আমরা যেতে চাই, আমি নিজেই এটা করতাম, তাদের সবচেয়ে ভালো স্বপ্ন থেকে দূরে থাকি, তারা বলে বাবা খুশি আমি যুদ্ধ করতে পারি, না হয় আমি তাকে সাহায্য করতে পারবো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفُضَيْلُ بْنُ مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏لِأَصْحَابِهِ أَمَا وَاللَّهِ لَقَدْ كُنْتُ أُحَدِّثُكُمْ أَنَّهُ لَوْ قَدْ اسْتَقَامَتْ الْأُمُورُ قَدْ آثَرَ عَلَيْكُمْ قَالَ فَرَدُّوا عَلَيْهِ رَدًّا عَنِيفًا قَالَ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَاءَهُمْ فَقَالَ لَهُمْ أَشْيَاءَ لَا أَحْفَظُهَا قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَكُنْتُمْ لَا تَرْكَبُونَ الْخَيْلَ قَالَ فَكُلَّمَا قَالَ لَهُمْ شَيْئًا قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَلَمَّا رَآهُمْ لَا يَرُدُّونَ عَلَيْهِ شَيْئًا قَالَ أَفَلَا تَقُولُونَ قَاتَلَكَ قَوْمُكَ فَنَصَرْنَاكَ وَأَخْرَجَكَ قَوْمُكَ فَآوَيْنَاكَ قَالُوا نَحْنُ لَا نَقُولُ ذَلِكَ يَا رَسُولَ اللَّهِ أَنْتَ تَقُولُهُ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا وَتَذْهَبُونَ أَنْتُمْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَا تَرْضَوْنَ أَنَّ النَّاسَ لَوْ سَلَكُوا وَادِيًا وَسَلَكْتُمْ وَادِيًا لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَرِشِي ‏ ‏وَأَهْلُ بَيْتِي ‏ ‏وَعَيْبَتِي ‏ ‏الَّتِي آوِي إِلَيْهَا فَاعْفُوا عَنْ مُسِيئِهِمْ وَاقْبَلُوا مِنْ مُحْسِنِهِمْ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏قُلْتُ ‏ ‏لِمُعَاوِيَةَ ‏ ‏أَمَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا أَنَّنَا ‏ ‏سَنَرَى بَعْدَهُ ‏ ‏أَثَرَةً ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏فَمَا أَمَرَكُمْ قُلْتُ أَمَرَنَا أَنْ نَصْبِرَ قَالَ فَاصْبِرُوا إِذًا ‏","","",""],[11415,11415,"","আমরা জয় করার চেষ্টা করেছি, আমরা একটি মাথাওয়ালা ছেলে, যে আমাদের সাথে কথা বলেছে, আমি তার জন্য ঈশ্বরের কাছে প্রার্থনা করছি এবং তিনি অনেক বছর আগে আপনার অনুসরণ করবেন. আমাদের সাথে ধৈর্য ধরে বলো যে ঈশ্বর আমাদের একবার একবার আমাদের এমন একজনকে খুঁজে বের করতে বলেছেন যিনি একসময় এমন একজন ব্যক্তি ছিলেন যিনি ছিলেন যিনি একজন । সে-ই তো-ই ব ্ যর ্ থ হয়েছে , যে নিজেকে স ্ বয়ংসমৃদ ্ ধ করেছে সে-ই তো তবে তার জন ্ য এ-সন ্ বন ্ ধে শ ্ রেষ ্ ঠ । আমিও আমার সাথে কথা বলেছি, আর আমার বাবা একজন শপথ শিল্পী হতে পেরে খুশি। স্যুট হঠাৎ করেই তার দুঃখ নিয়ে পালিয়ে যাবে। এমনকি তারও সামনে এগিয়ে যাচ্ছি। ওর লোক চুমু খাচ্ছে বলে... ...কোন ভয়ানক কথা বলার জন্য","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَتَتَّبِعُنَّ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلُوا جُحْرَ ضَبٍّ لَتَبِعْتُمُوهُمْ قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏قَالَ فَمَنْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنِي ‏ ‏شَهْرٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فِي غُنَيْمَةٍ لَهُ يَهُشُّ عَلَيْهَا فِي ‏ ‏بَيْداءِ ذِي الْحُلَيْفَةِ ‏ ‏إِذْ عَدَا عَلَيْهِ ذِئْبٌ فَانْتَزَعَ شَاةً مِنْ غَنَمِهِ ‏ ‏فَجَهْجَأَهُ ‏ ‏الرَّجُلُ فَرَمَاهُ بِالْحِجَارَةِ حَتَّى اسْتَنْقَذَ مِنْهُ شَاتَهُ ثُمَّ إِنَّ الذِّئْبَ أَقْبَلَ حَتَّى ‏ ‏أَقْعَى ‏ ‏مُسْتَذْفِرًا ‏ ‏بِذَنَبِهِ مُقَابِلَ الرَّجُلِ ‏ ‏فَذَكَرَهُ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏","","",""],[11416,11416,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং দুটো গ্রাম বা কাদের দ্বারা তাকে মৃত অবস্থায় পাওয়া যাবে, সেই সম্বন্ধে তিনি আমাদের বলেছিলেন । আমি যেমন বলেছিলাম, তাদের কথাই চিন্তা করতাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْرَائِيلَ إِسْمَاعِيلُ الْمُلَائِيُّ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وُجِدَ قَتِيلٌ بَيْنَ قَرْيَتَيْنِ ‏ ‏أَوْ مَيِّتٌ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذُرِعَ مَا بَيْنَ الْقَرْيَتَيْنِ إِلَى أَيِّهِمَا كَانَ أَقْرَبَ فَوُجِدَ أَقْرَبَ إِلَى أَحَدِهِمَا بِشِبْرٍ قَالَ فَكَأَنِّي أَنْظُرُ إِلَى شِبْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَهُ عَلَى الَّذِي كَانَ أَقْرَبَ ‏","","",""],[11417,11417,"","আমরা আমাদের বাবার সবচেয়ে ভালো বাবার সাথে কথা বলেছি, বাবা আর বাবার মধ্যে দু’বার আমার বাবার সাথে দু’জন বাবা-মা আছে। যে তাদেরকে হত্যা করার শক্তি দিয়ে... ...তাদের মধ্যে সবচেয়ে ভাল, লর্ড তার জন্য প্রার্থনা করে...","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ أَبِي أَنَسٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏و حَدَّثَنَاه ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏تَمَارَى ‏ ‏رَجُلَانِ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى فَقَالَ أَحَدُهُمَا هُوَ ‏ ‏مَسْجِدُ قُبَاءٍ ‏ ‏وَقَالَ الْآخَرُ هُوَ ‏ ‏مَسْجِدُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ ‏ ‏مَسْجِدِي ‏ ‏هَذَا ‏","","",""],[11418,11418,"","আমি বধিরদের পিছন থেকে কথা বলেছি আর আমি একজন সিনিয়র। আমি আমার বাবার সাথে ঈশ্বরের পরে কথা বলেছি। আমার বাবা বলেছিলেন যে আমার পিতা আমার প্রভুর দাস। আমি এবং আমি রবিবার সকালে তাদের মাথা ন্যাড়া করতে এবং মাথা বিকৃত করতে যাচ্ছি। যখন সে শপথ করে শপথ করে শপথ নিয়ে শপথ নিয়ে শপথ নিয়ে শপথ করে তাকে কবর দেওয়া হয়। ঈশ্বর দুই জয়ের জন্য আত্মসমর্পণ করেছেন। আর বাবা আমার ছেলের কাছ থেকে আমার বিজয় দেখেছে... ...তাই বলে যে বাবা এখন খুশি হবে যে, সে শুধু মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي إِبْرَاهِيمَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابَهُ حَلَّقُوا رُءُوسَهُمْ عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏غَيْرَ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏وَأَبِي قَتَادَةَ ‏ ‏فَاسْتَغْفَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُحَلِّقِينَ ثَلَاثَ مِرَارٍ وَلِلْمُقَصِّرِينَ مَرَّةً ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏أَبَا إِبْرَاهِيمَ الْأَنْصَارِيَّ ‏ ‏مِنْ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏قَالَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[11419,11419,"","আমি আমার বাবার সাথে কথা বলেছি আমার বাবার খুশি হওয়ার কথা। খোদা তার কাছে প্রার্থনা করেছিলেন এবং এই পাইপের মিশ্রণের মাধ্যমে তাকে আত্মসমর্পণ করে এবং তার কাছে আত্মসমর্পণ করে এবং এই রহস্য এবং রহস্যটি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ خَلِيطِ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ ‏","","",""],[11420,11420,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ডাক্তার, দুঃখ, দুঃখ, দুঃখ, দুঃখ, দুঃখ, ক্ষমার জন্য আত্মসমর্পণ করবেন । রক্ষক, স্করম, স্করম, বস্তা, সেলাই, সেলাই, সেলাই, সেলাই, সেলাই, সেলাই, সেলাই, মাখন আর রহস্য.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا ثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَنْ يُخْلَطَ بَيْنَ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ ‏","","",""],[11421,11421,"","ডাক্তার, বিশুদ্ধ, নকল বিশ্ব সম্পর্কে, ডাক্তার, বিশুদ্ধতা এবং মিথ্যা বিশ্ব সম্পর্কে তিনি খুশির সাথে কথা বলেছিলেন। উপরে এবং পাশ দিয়ে হেঁটে যাওয়া মাখন।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَنْ يُخْلَطَ بَيْنَ الزَّبِيبِ وَالتَّمْرِ ‏ ‏وَالْبُسْرِ ‏ ‏وَالتَّمْرِ ‏","","",""],[11422,11422,"","আমরা বাবার সবচেয়ে খুশির কথা বলেছি যে সে ঈশ্বরের কাছে যেতে পারবে। ডাক্তার আর আলো সম্পর্কে... ...আর নকলটা তোমার ক্লাসে করতে বলা হয়েছে নাকি আমরা একবার কথা বলেছি আমার বাবা আমার খুশি দাসের কথা বলেছিলেন... ...আমার একমাত্র সেই লোক যাকে পাপ থেকে বাঁচাতে হবে, ঈশ্বর যাজকদের কাপড় থেকে আত্মসমর্পণ করেছেন, যেমনটা তারা বলেছিল ঈশ্বরের ইচ্ছা বেঁচে থাকবে আর ঈশ্বর বলেছেন যে আমরা বেঁচে আছি আর ঈশ্বর কখনো লর্ড ছিলেন না, তিনি একটি ঘটনা বলেছেন, আর তিনি উল্লেখ করেছেন যে ভিক ব্যর্থ হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَقَالَ ‏ ‏انْتَبِذْ ‏ ‏فِي ‏ ‏سِقَائِكَ ‏ ‏وَأَوْكِهِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنِي ‏ ‏مَنْ لَقِيَ ‏ ‏الْوَفْدَ الَّذِينَ قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏فِيهِمْ ‏ ‏الْأَشَجُّ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّا حَيٌّ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ ‏ ‏مُضَرَ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏يَحْيَى ‏ ‏وَلَمْ يَذْكُرْ أَنَّ فِيكَ ‏ ‏خَلَّتَيْنِ ‏","","",""],[11423,11423,"","আমি আমার বাবাকে সাহায্য করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّى الْقَصِيرُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الشُّرْبِ فِي ‏ ‏الْحَنْتَمَةِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[11424,11424,"","আমরা আমার ছেলে বাবার সাথে আমার বাবার মত কথা বলেছি, সে মানুষকে আগুনে পুড়িয়ে দেয়া হবে, আর তারা ছিলো সার্কুলারের মত, আর তারপর সে তার সাথে তারা রাতের পিপেসি, আমার বাবার কথা বলছি, তাকে খুশি করে বলতে যে সে ঈশ্বরের কাছে প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَخْرُجُ نَاسٌ مِنْ النَّارِ قَدْ احْتَرَقُوا وَكَانُوا مِثْلَ الْحُمَمِ ثُمَّ لَا يَزَالُ أَهْلُ الْجَنَّةِ يَرُشُّونَ عَلَيْهِمْ الْمَاءَ حَتَّى يَنْبُتُونَ نَبَاتَ ‏ ‏الْغُثَاءِ ‏ ‏فِي السَّيْلِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ سَيَخْرُجُ نَاسٌ مِنْ النَّارِ ‏ ‏فَذَكَرَهُ ‏","","",""],[11425,11425,"","আমরা আমার বাবার কথা বলেছিলাম তার বাবার জন্য প্রার্থনা করতে ক্লান্ত হয়ে পড়ে, তুমি আগুন ধরে উঠেছো, তারা হয়তো অন্ধকারে ছিল তারা বলছে তারা শহরে এবং শহরে নিজেদেরকে মেরে ফেলবে। রাতের পথে ভালবাসা বলতে হয় যেন তুমি ঈশ্বরের উপত্যকা থেকে এসেছ","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَخْرُجُ ‏ ‏ضُبَارَةٌ ‏ ‏مِنْ النَّارِ قَدْ كَانُوا فَحْمًا قَالَ فَيُقَالُ بُثُّوهُمْ فِي الْجَنَّةِ وَرُشُّوا عَلَيْهِمْ مِنْ الْمَاءِ قَالَ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ كَأَنَّكَ كُنْتَ مِنْ أَهْلِ الْبَادِيَةِ يَا رَسُولَ اللَّهِ ‏","","",""],[11426,11426,"","আমরা তোমার টাকা ঈশ্বরের ছেলের দ্বারা ধাঁধার ব্যাপারে কথা বলেছি, আমি আমার বাবাকে যেতে দিয়েছি, তাকে বলতে চাই আমি সুখী। ঈশ্বর আদেশ দিয়েছেন, ঈশ্বর তাকে তোমার ছেলেকে আত্মসমর্পণ করবে। অনুগত ব্যক্তিরা এমন বাড়িতে প্রবেশ করবে না, যেখানে আপনি আমার হাত প্রতিনিধিত্ব করেন বা আকার করেন না ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏أَنَّ ‏ ‏رَافِعَ بْنَ إِسْحَاقَ ‏ ‏أَخْبَرَهُ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي طَلْحَةَ ‏ ‏عَلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏نَعُودُهُ ‏ ‏فَقَالَ ‏ ‏لَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَخْبَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ تَمَاثِيلُ ‏ ‏أَوْ صُورَةٌ شَكَّ ‏ ‏إِسْحَاقُ ‏ ‏لَا يَدْرِي أَيَّتَهُمَا قَالَ ‏ ‏أَبُو سَعِيدٍ ‏","","",""],[11427,11427,"","আমরা বাবার মৃত্যুর পর্দার ব্যাপারে কিছু বাজে মনের কথা বলেছি, ঈশ্বর আমার বাবার সুখী দাসকে ছেড়ে চলে গেছেন, আমি তাদের কোম্পানির কাছে চ্যালেঞ্জ করেছি বলে যে, এটা চলে গেছে। আর আমার বাবার নাম তার কানে যা আমি দেখি তা বলার দু:খের কথা তার কানে আছে।","‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُمَيْرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏جَلَسْتُ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَقَالَ ‏ ‏أَحَدُهُمَا لِصَاحِبِهِ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ أَنَّهُ ‏ ‏يَبْلُغُ الْعَرَقُ مِنْ النَّاسِ يَوْمَ الْقِيَامَةِ ‏ ‏فَقَالَ ‏ ‏أَحَدُهُمَا إِلَى شَحْمَتِهِ ‏ ‏وَقَالَ ‏ ‏الْآخَرُ ‏ ‏يُلْجِمُهُ ‏ ‏فَخَطَّ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَأَشَارَ ‏ ‏أَبُو عَاصِمٍ ‏ ‏بِأُصْبُعِهِ ‏ ‏مِنْ أَسْفَلِ شَحْمَةِ أُذُنَيْهِ إِلَى ‏ ‏فِيهِ فَقَالَ مَا أَرَى ذَاكَ إِلَّا سَوَاءً ‏","","",""],[11428,11428,"","আমরা বলেছিলাম কিভাবে আমরা আপনার টাকা বলি এবং দিনের সাজে সাজানোর সাথে লটকে মুগ্ধ হয়ে যাই। ঈশ্বরের কাছে প্রার্থনা করা উচিত এবং তিনি তাই বলবেন। তিনি বলেন, আপনি আরো বেশি কিছু। আপনি কি জানেন, আপনি কি বলেন? আপনি কি বলেন, আপনি কি বলেন, আপনি কি বলেন, আপনি নাকি আপনার টাকা দিয়ে দিনের জন্য? আপনি কি বলেন? আপনি কি বলেন? আপনি কি আছে? আপনি কি? আপনি জানেন, আপনি জানেন, আপনি কি? আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন না। আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি আপনার জন্য একটি ছোট ছোট ছোট ছোট ছোট পরিবার আছে। এবং আপনার জন্য একটি সংখ্যা, এবং আপনার কাছে আপনি একটি সংখ্যা যোগ করুন। অনুমতি.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏وَيُونُسُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ الْمُؤَذِّنَ ‏ ‏وَقَالَ ‏ ‏مَالِكٌ ‏ ‏الْمُنَادِيَ ‏ ‏فَقُولُوا مِثْلَ يَقُولُ ‏ ‏زَادَ ‏ ‏مَالِكٌ ‏ ‏الْمُؤَذِّنَ ‏","","",""],[11429,11429,"","আমরা এটা জেনে ভাল কথা বলেছি যে একটা ছেলে ব্যর্থ হয়েছে, খুশি হবার জন্য, সে তার কাজ থেকে শুনেছি যে আমরা তাকে হারিয়েছি। এমনকি আমরা একটা বিল্ডিং বানাতেও কথা বলেছি যা গোপন থাকবে। সে ঈশ্বরের ইচ্ছা থেকে পালিয়েছে... ...এবং তাকে পালানোর জন্য পৌঁছে দিবে... ...আর আমি যা করছি তা করার জন্য. কারণ সে নিজেকে মেরে ফেলার চেষ্টা করছে, আর তারা তাকে আগুন বলে... ...সে বলছে যে আমি তার আত্মার মুক্তির জন্য স্বস্তি পাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏مَحْبُوبُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ لَهُ وَلِابْنِهِ ‏ ‏عَلِيٍّ ‏ ‏انْطَلِقَا إِلَى ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَاسْمَعَا مِنْ حَدِيثِهِ قَالَ فَانْطَلَقْنَا فَإِذَا هُوَ فِي ‏ ‏حَائِطٍ ‏ ‏لَهُ فَلَمَّا ‏ ‏رَآنَا أَخَذَ رِدَاءَهُ فَجَاءَنَا فَقَعَدَ فَأَنْشَأَ يُحَدِّثُنَا حَتَّى أَتَى عَلَى ذِكْرِ بِنَاءِ الْمَسْجِدِ قَالَ كُنَّا نَحْمِلُ ‏ ‏لَبِنَةً ‏ ‏لَبِنَةً ‏ ‏وَعَمَّارُ بْنُ يَاسرٍ ‏ ‏يَحْمِلُ ‏ ‏لَبِنَتَيْنِ ‏ ‏لَبِنَتَيْنِ ‏ ‏قَالَ فَرَآهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَنْفُضُ التُّرَابَ عَنْهُ وَيَقُولُ يَا ‏ ‏عَمَّارُ ‏ ‏أَلَا تَحْمِلُ ‏ ‏لَبِنَةً ‏ ‏كَمَا يَحْمِلُ أَصْحَابُكَ قَالَ إِنِّي أُرِيدُ الْأَجْرَ مِنْ اللَّهِ قَالَ فَجَعَلَ يَنْفُضُ التُّرَابَ عَنْهُ وَيَقُولُ وَيْحَ ‏ ‏عَمَّارٍ ‏ ‏تَقْتُلُهُ ‏ ‏الْفِئَةُ ‏ ‏الْبَاغِيَةُ ‏ ‏يَدْعُوهُمْ إِلَى الْجَنَّةِ وَيَدْعُونَهُ إِلَى النَّارِ قَالَ فَجَعَلَ ‏ ‏عَمَّارٌ ‏ ‏يَقُولُ أَعُوذُ بِالرَّحْمَنِ مِنْ الْفِتَنِ ‏","","",""],[11430,11430,"","আমরা ঈশ্বরকে কথা বলেছিলাম কিন্তু আমার বাবা মাদক খণ্ডন করার চেষ্টা করেছিলেন। এটা ঈশ্বরের ইচ্ছা ছিল, ঈশ্বর তা করেছেন এবং তিনি জীবিত আছেন। আমরা তাকে চিনি। তার মুখে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي عُتْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ حَيَاءً مِنْ الْعَذْرَاءِ فِي ‏ ‏خِدْرِهَا ‏ ‏وَكَانَ إِذَا كَرِهَ الشَّيْءَ عَرَفْنَاهُ فِي وَجْهِهِ ‏","","",""],[11431,11431,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম, যিনি আমাকে সাহায্য করার চেষ্টা করছেন । আমি চেষ্টা করে বলছি, \"সে বলল, সে কখনো তার ঋণ এবং ওজনের ভুলের কাছে নতিস্বীকার করেনি।\" অন্ধকার আমার বাবার কথা এটা বলতে পারবে না যে আমার বাবার বাবার অন্ধকার ঈশ্বর আমাদের সময়ের জন্য রক্ষা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أُنَيْسُ بْنُ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ وَهُوَ عَاصِبٌ رَأْسَهُ قَالَ فَاتَّبَعْتُهُ حَتَّى صَعِدَ عَلَى الْمِنْبَرِ قَالَ فَقَالَ ‏ ‏إِنِّي السَّاعَةَ لَقَائِمٌ عَلَى الْحَوْضِ قَالَ ثُمَّ قَالَ إِنَّ عَبْدًا عُرِضَتْ عَلَيْهِ الدُّنْيَا وَزِينَتَهَا فَاخْتَارَ الْآخِرَةَ فَلَمْ ‏ ‏يَفْطَنْ ‏ ‏لَهَا أَحَدٌ مِنْ الْقَوْمِ إِلَّا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ بِأَبِي أَنْتَ وَأُمِّي بَلْ ‏ ‏نَفْدِيكَ بِأَمْوَالِنَا وَأَنْفُسِنَا وَأَوْلَادِنَا قَالَ ثُمَّ هَبَطَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمِنْبَرِ فَمَا رُئِيَ عَلَيْهِ حَتَّى السَّاعَةِ ‏","","",""],[11432,11432,"","আমি আমার বাবা আমাকে সাহায্য করার চেষ্টা করে কথা বলেছি, আর আমি এত ভাল হয়ে থাকতে পেরে ক্লান্ত হয়ে গেছি, সে ঈশ্বরের কাছে প্রার্থনা করছে যদি আছে, আমার মসজিদ এটা, আর তুমি। খুব ভাল.","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنَا ‏ ‏أُنَيْسُ بْنُ أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏وَرَجُلًا مِنْ ‏ ‏بَنِي خُدْرَةَ ‏ ‏امْتَرَيَا ‏ ‏فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى فَقَالَ ‏ ‏الْعَوْفِيُّ ‏ ‏هُوَ ‏ ‏مَسْجِدُ قُبَاءٍ ‏ ‏وَقَالَ ‏ ‏الْخُدْرِيُّ ‏ ‏هُوَ ‏ ‏مَسْجِدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَاهُ عَنْ ذَلِكَ فَقَالَ هُوَ ‏ ‏مَسْجِدِي ‏ ‏هَذَا وَفِي ذَلِكَ خَيْرٌ كَثِيرٌ ‏","","",""],[11433,11433,"","বাবার সাথে আমার বাবার এত কথা বলে আমি আমার বাবার সাথে কথা বলেছিলাম, আমার বাবা ঈশ্বরের অনুগ্রহে বসে খুশি। আমি ভয় পাচ্ছি, মানুষের আত্মার থেকে দূরে থাকা উচিৎ। তার কাছে প্রার্থনা করেছেন, ঈশ্বর তাকে প্রার্থনা করেছেন এবং তাকে কখনোই আশ্বস্ত করতে বলেছেন না যে ঈশ্বর তাকে শান্তি এবং ঈশ্বরের কাছে সমর্পণ করেছেন। আমরা তাকে নিচে ফেলে দিয়েছিলাম, তিনি বলেছিলেন তাকে হারতে হবে। আত্মা, এটা খারাপ যে ভালোটা মারা যাচ্ছে বা তার জন্য দোষ দেয়া হয়েছে। সূর্য ভেঙ্গে গেছে আর তার মানে হচ্ছে কৌশলটা করা হয়েছে। আর তার ছেলেকে স্পর্শ করা। ঈশ্বরকে বলা হয়েছে, তার কাছে পৌঁছে দিতে হবে আর যদি তাকে এটা নিতে হয়, তাহলে তাকে নিয়ে যেতে হবে। যে তাকে তোমাকে আত্মসমর্পণ করতে বলেছে, তার জন্য তাকে দায়ী করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ وَجَلَسْنَا حَوْلَهُ فَقَالَ ‏ ‏إِنَّمَا ‏ ‏أَخَافُ عَلَيْكُمْ بَعْدِي مَا يُفْتَحُ عَلَيْكُمْ مِنْ زَهْرَةِ الدُّنْيَا وَزِينَتِهَا فَقَالَ رَجُلٌ ‏ ‏أَوَيَأْتِي الْخَيْرُ بِالشَّرِّ يَا رَسُولَ اللَّهِ فَسَكَتَ عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَهُ مَا شَأْنُكَ تُكَلِّمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا يُكَلِّمُكَ قَالَ وَأُرِنَا أَنَّهُ يُنْزَلُ عَلَيْهِ قَالَ فَأَفَاقَ يَمْسَحُ عَنْهُ ‏ ‏الرُّحَضَاءَ ‏ ‏وَقَالَ أَيْنَ هَذَا السَّائِلُ وَكَأَنَّهُ حَمِدَهُ فَقَالَ إِنَّهُ ‏ ‏لَا يَأْتِي الْخَيْرُ بِالشَّرِّ إِنَّ مِمَّا يُنْبِتُ الرَّبِيعُ يَقْتُلُ أَوْ ‏ ‏يُلِمُّ ‏ ‏إِلَّا آكِلَةَ الْخَضِرِ فَإِنَّهَا أَكَلَتْ حَتَّى إِذَا ‏ ‏امْتَلَأَتْ خَاصِرَتَاهَا ‏ ‏اسْتَقْبَلَتْ عَيْنَ الشَّمْسِ ‏ ‏فَثَلَطَتْ ‏ ‏وَبَالَتْ ثُمَّ ‏ ‏رَتَعَتْ ‏ ‏وَإِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةً وَنِعْمَ صَاحِبُ الْمُسْلِمِ هُوَ لِمَنْ أَعْطَى مِنْهُ الْيَتِيمَ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ ‏ ‏أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ الَّذِي يَأْخُذُهُ بِغَيْرِ حَقِّهِ كَالَّذِي يَأْكُلُ وَلَا يَشْبَعُ فَيَكُونُ عَلَيْهِ شَهِيدًا يَوْمَ الْقِيَامَةِ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ عَلَى الْمِنْبَرِ ذَاتَ يَوْمٍ فَقَالَ ‏ ‏إِنَّ مِمَّا أَخْشَى عَلَيْكُمْ فَذَكَرَ الْحَدِيثَ وَقَالَ يَقْتُلُ حَبَطًا أَوْ ‏ ‏يُلِمُّ ‏","","",""],[11434,11434,"","আমার বাবা তার জন্য প্রার্থনা করার পর আমার বাবার সঙ্গে খুশি হয়ে কথা বলেছিলেন । ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমাদের শহরে ও শহরে আমাদের আশীর্বাদের জন্য আপনাদের কাছে আত্মসমর্পণ করেছেন । তোমার আশীর্বাদের পিছনে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بَعْثًا إِلَى ‏ ‏بَنِي لَحْيَانَ ‏ ‏مِنْ ‏ ‏بَنِي هُذَيْلٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏مِنْ ‏ ‏هُذَيْلٍ ‏ ‏قَالَ لِيَنْبَعِثْ مِنْ كُلِّ رَجُلَيْنِ أَحَدُهُمَا وَالْأَجْرُ بَيْنَهُمَا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏مُدِّنَا ‏ ‏وَصَاعِنَا ‏ ‏وَاجْعَلْ مَعَ الْبَرَكَةِ بَرَكَتَيْنِ ‏","","",""],[11435,11435,"","আমরা এমন আবেগ দিয়ে চেষ্টা করেছি, যা আমার বাবার পুরনো জীবনের জন্য আমাকে বড় করে তুলেছে। আল্লাহকে বাঁচাও, আমি তোমার মনে মনে রাখতে পারি তুমি কি বলবে... ...সে বলবে তুমি কি বলবে না যে আমি ভয় পাচ্ছি মানুষ বলবে যে আমি প্রতারণা করতে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا يَحْقِرَنَّ أَحَدُكُمْ نَفْسَهُ إِذَا رَأَى أَمْرَ اللَّهِ عَلَيْهِ فِيهِ مَقَالًا فَلَا يَقُولُ بِهِ ‏ ‏فَيَلْقَى اللَّهَ وَقَدْ أَضَاعَ ذَلِكَ فَيَقُولُ ‏ ‏مَا مَنَعَكَ فَيَقُولُ خَشِيتُ النَّاسَ فَيَقُولُ أَنَا ‏ ‏كُنْتُ أَحَقَّ أَنْ ‏ ‏تَخْشَى ‏","","",""],[11436,11436,"","আমরা আমাদের আবেগ-অনুভূতি দিয়ে চেষ্টা করেছি, আমার ভালবাসার চেষ্টা করেছি। লর্ড তার জন্য প্রার্থনা করেছে এবং আমি নিজেকে আত্মসমর্পণ করতে চাই না। অতীতে যারা কথা বলতে চায়, তাদের শুভ হোক, যে কিনা বিছানায় ছিল, যতক্ষণ না আমরা আমাদের মন হারিয়ে ফেলেছি এবং আমরা সূর্যের মধ্যে থাকব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ مَخَافَةُ النَّاسِ أَنْ يَتَكَلَّمَ بِحَقٍّ إِذَا عَلِمَهُ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏فَمَا زَالَ بِنَا الْبَلَاءُ حَتَّى قَصَّرْنَا وَإِنَّا لَنَبْلُغُ فِي الشَّرِّ ‏ ‏و قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏","","",""],[11437,11437,"","আমার আগের স্ত্রী তার জন্য প্রার্থনা করে এবং বিগত দুই মাসে তার আত্মসমর্পণ করবে আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার পালনকর ্ তা সম ্ প ্ রদায় প ্ রত ্ যেক ; ; ; আপনি আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার পালনকর ্ তাই নন , যা , , অতঃপর আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার আপনার মালিক, আপনার নিজের মালিক, আপনার এই গুণটি নিয়ে আমি কিভাবে কথা বলব তা বলবো না। আরেকটা।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَمَانِ عَشَرَ مَضَتْ مِنْ رَمَضَانَ ‏ ‏فَصَامَ صَائِمُونَ وَأَفْطَرَ مُفْطِرُونَ فَلَمْ يَعِبْ هَؤُلَاءِ عَلَى هَؤُلَاءِ وَلَا هَؤُلَاءِ عَلَى هَؤُلَاءِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي بِهَذَا الْحَدِيثِ أَرْبَعَةٌ أَحَدُهُمْ ‏ ‏قَتَادَةُ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏قَتَادَةَ ‏","","",""],[11438,11438,"","আমরা এই কামনায় বাপ্তাইজিত হয়েছি যে আমরা একটা রীতি তৈরি করেছি যা বিচারালয়ের প্রতি ভালোবাসার প্রয়োজন তৈরি করেছে। তিনি বলেছিলেন: “আমি যখন আমার ছেলে ও আমার স্ত্রী যিহোবার সাক্ষিদের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম, তখন আমি বুঝতে পেরেছিলাম যে, আমার কাছে আর কোনো খবর নেই । ঈশ্বর তাঁর শান্তি এবং আপনার ভাইয়ের বিরুদ্ধে পাপ করেছেন বলে তার ভাই তার কাছে হারালেন । ( খ) কীভাবে আমরা জানি যে, যিহোবা আমাদের জন্য চিন্তা করেন?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَخِي انْطَلَقَ بَطْنُهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْقِهِ عَسَلًا فَسَقَاهُ فَقَالَ إِنِّي سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ لَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ جَاءَهُ الرَّابِعَةَ فَقَالَ اسْقِهِ عَسَلًا فَقَالَ قَدْ سَقَيْتُهُ فَلَمْ يَزِدْهُ إِلَّا ‏ ‏اسْتِطْلَاقًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ اللَّهُ وَكَذَبَ بَطْنُ أَخِيكَ فَسَقَاهُ ‏ ‏فَبَرِئَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُتَوَكِّلِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[11439,11439,"","আমরা আমাদের আবেগে বাপ্তাইজিত হয়েছি... ...আমরা একটা রীতিতে... ...আমি বলতে চাই যে আমি... প্রভু, সে তাদের সাথে প্রতারণা করবে, অথবা এক দানবকে তাদের সাথে মিথ্যা বলবে, আমার কেউ নেই, এমনকি তাদের মিথ্যা কথা পর্যন্ত বিশ্বাস করে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏أَوْ ‏ ‏أَبِي سُلَيْمَانَ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏وَقَالَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَيَكُونُ أُمَرَاءُ ‏ ‏يَغْشَاهُمْ ‏ ‏غَوَاشٍ ‏ ‏أَوْ ‏ ‏حَوَاشٍ ‏ ‏مِنْ النَّاسِ يَظْلِمُونَ وَيَكْذِبُونَ فَمَنْ أَعَانَهُمْ عَلَى ظُلْمِهِمْ وَصَدَّقَهُمْ بِكَذِبِهِمْ فَلَيْسَ مِنِّي وَلَا أَنَا مِنْهُ وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ فَأَنَا مِنْهُ وَهُوَ مِنِّي ‏","","",""],[11440,11440,"","আমরা চেষ্টা করে যাচ্ছি একটা বক্তৃতার জন্য, যা আমার কাছে বলা হয়েছে, যেন আমরা ঈশ্বরের প্রতি ভালবাসা অনুভব করার ঐতিহ্যের কথা বলেছিলাম। তোমার টাকা বলেছে আমি বাবাকে খুশি করতে শুনেছি, সে তার গালের মধ্যে খুঁজে পাওয়ার স্বপ্ন দেখে, আর তারপর সে তাকে কিছু জানতে চায়.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏ابْنُ عُتْبَةَ ‏ ‏مَوْلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ حَيَاءً مِنْ عَذْرَاءَ فِي ‏ ‏خِدْرِهَا ‏ ‏وَكَانَ إِذَا كَرِهَ شَيْئًا عَرَفْنَاهُ فِي وَجْهِهِ ‏","","",""],[11441,11441,"","আমরা একটা প্রথা নিয়ে কথা বলেছি... ...যে ব্যাপারে আমরা শুনেছি... ...সে আমার ভালোবাসা নিয়ে বাবা কথা বলছে. ঈশ্বর রাজ্য ও তাদের আকাঙ্ক্ষাকে দূর করে দিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّهُمَا ‏ ‏شَهِدَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَقْعُدُ قَوْمٌ يَذْكُرُونَ اللَّهَ إِلَّا ‏ ‏حَفَّتْهُمْ ‏ ‏الْمَلَائِكَةُ وَغَشِيَتْهُمْ الرَّحْمَةُ وَنَزَلَتْ عَلَيْهِمْ ‏ ‏السَّكِينَةُ ‏ ‏وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ ‏","","",""],[11442,11442,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমরা একটা ছেলে যে হারিয়ে গেছে তার একটা রীতি নিয়ে... ...সে বলল যে, তার কাছে প্রার্থনা করার আগে সে হয়তো অনেক কিছু হারিয়েছে, ফাদার, আমরা ঈশ্বরের কাছে প্রার্থনা করেছি, আর আপনাদের কাছে আত্মসমর্পণ করেছি, সে তাকে নামিয়ে আনতে পারে, তারপর আমি সঠিকটা করব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏خَطَبَ قَبْلَ الصَّلَاةِ فَقَالَ لَهُ رَجُلٌ الصَّلَاةُ قَبْلَ الْخُطْبَةِ فَقَالَ لَهُ ‏ ‏مَرْوَانُ ‏ ‏تُرِكَ ذَاكَ يَا أَبَا فُلَانٍ فَقَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُنْكِرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَاكَ أَضْعَفُ الْإِيمَانِ ‏","","",""],[11443,11443,"","আমরা বাবা-এর সাথে কথা বলেছি, যখন আমরা বাবাকে সাহায্য করতে শুরু করলাম, সে প্রার্থনা করছিল আমরা যেন ঈশ্বরের কাছে প্রার্থনা করি, যেন তিনি তার জন্য প্রার্থনা করেন এবং যখন তিনি উপস্থিত থাকেন, তখন তিনি তার নিজের কথা তুলে ধরেন। তার কিছু প্রার্থনা, যখন মানুষ তোমাকে এটা করতে দেখে, আমি যা বলেছি, আমি তাই বলব। আমরা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন যে আমার ড্রাগন আমাকে বলছে যে তার আছে। বলা হয়েছে যে তাকে বলা হয়েছে যে তাকে বলা হয়েছে তাকে বলা হয়েছে, সে বলেছে, আমি তাদের খুঁজে বের করব, তারপর আমি তাদের দেখছি। তিনি বলেন আমার বাবা এই আলোচনায় আসেন নি, যখন তিনি খোলা অবস্থায় ছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو نَعَامَةَ السَّعْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَلَمَّا كَانَ فِي بَعْضِ صَلَاتِهِ خَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ فَلَمَّا رَأَى النَّاسُ ذَلِكَ خَلَعُوا نِعَالَهُمْ فَلَمَّا قَضَى صَلَاتَهُ قَالَ مَا بَالُكُمْ أَلْقَيْتُمْ نِعَالَكُمْ قَالُوا رَأَيْنَاكَ أَلْقَيْتَ نَعْلَيْكَ فَأَلْقَيْنَا نِعَالَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏أَتَانِي فَأَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا ‏ ‏أَوْ قَالَ أَذًى ‏ ‏فَأَلْقَيْتُهُمَا فَإِذَا جَاءَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَلْيَنْظُرْ فِي نَعْلَيْهِ فَإِنْ رَأَى فِيهِمَا قَذَرًا ‏ ‏أَوْ قَالَ أَذًى ‏ ‏فَلْيَمْسَحْهُمَا وَلْيُصَلِّ فِيهِمَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَمْ يَجِئْ فِي هَذَا الْحَدِيثِ بَيَانُ مَا كَانَ فِي النَّعْلِ ‏","","",""],[11444,11444,"","আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছিলাম, আমার বাবা, লর্ডকে ফোন করে, তুমি তাকে এটা পৌঁছে দিতে বলেছিলে। তুমি এটা করো যে এটা হয়তো না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ ‏ ‏إِنْ تَفْعَلُوا ذَلِكَ لَا عَلَيْكُمْ أَنْ لَا تَفْعَلُوهُ فَإِنَّهُ لَيْسَ ‏ ‏نَسَمَةٌ ‏ ‏قَضَى اللَّهُ أَنْ تَكُونَ إِلَّا هِيَ ‏ ‏كَائِنَةٌ ‏","","",""],[11445,11445,"","আমরা কথা বলেছিলাম আমরা কত ভালো কথা বলেছি, হয়তো আমি অনুমান করছি, নবী তার কাছে প্রার্থনা করেছিলেন এবং তিনি এমন একটা আংটি খুঁজে বের করতেন যেটা আবার চেষ্টা করা হয়েছিল। আপনি অনুমান করছেন আমি নিশ্চিত যে, আমি নিশ্চিত। আমি জানি, আমি কি বলছি, আমি জানি। আমি জানি, আমি জানি, আমি জানি, আমি কি বলছি, এটা অনুমান করা যায় যে এটা চলে যাওয়ার আগে, অন্ধ হতে বা অন্য কিছু হতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَخْبَرَهُ ‏ ‏وَأَبُو هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي جِدَارِ الْمَسْجِدِ ‏ ‏نُخَامَةً ‏ ‏فَتَنَاوَلَ حَصَاةً ‏ ‏فَحَتَّهَا ‏ ‏ثُمَّ قَالَ ‏ ‏إِذَا ‏ ‏تَنَخَّمَ ‏ ‏أَحَدُكُمْ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏قِبَلَ وَجْهِهِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[11446,11446,"","আমরা ফুল দিয়ে অনেক উপকার করেছি আমি আমার নিজের মাংসকে বলতে পারি যে আমাকে ডাকা হয়েছে এবং মার্শালিস্ট বলে যে তিনি ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি একটি মুক্তি পাবেন হলওয়েতে রিং করে তিনি বলেছিলেন, কেউ কলমে থাকবে না, তার নিজের হাতে গাড়ি চালানোর অধিকার নেই।","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولَانِ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُخَامَةً ‏ ‏فِي الْقِبْلَةِ فَتَنَاوَلَ حَصَاةً فَحَكَّهَا بِهَا ثُمَّ قَالَ ‏ ‏لَا ‏ ‏يَتَنَخَّمْ ‏ ‏أَحَدٌ فِي الْقِبْلَةِ وَلَا عَنْ يَمِينِهِ وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ رِجْلِهِ الْيُسْرَى ‏","","",""],[11447,11447,"","আমরা আমার বাবার ভালো কাজ করার ব্যাপারে দুই সাহস নিয়ে কথা বলেছি, সে বলে সে যেতে আর সময় নষ্ট করতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَزْنًا بِوَزْنٍ ‏","","",""],[11448,11448,"","আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছেন যেন তিনি ঈশ্বরকে এবং তাঁর তাঁর ও তাঁর বাবাকে রক্ষা করেন । তারা তোমাকে যত বেশি জানে, তুমি জানো যে তোমার মুখে কতটা ভাল ঘুমোচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ يَعْنِي ابْنَ أَبِي حَفْصَةَ ‏ ‏وَالْأَعْمَشُ ‏ ‏وَعَبْدُ اللَّهِ بْنُ صُهْبَانَ ‏ ‏وَكَثِيرٌ النَّوَّاءُ ‏ ‏وَابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى ‏ ‏لَيَرَاهُمْ مَنْ تَحْتَهُمْ كَمَا تَرَوْنَ النَّجْمَ الطَّالِعَ فِي أُفُقٍ مِنْ آفَاقِ السَّمَاءِ أَلَا وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[11449,11449,"","আমরা বাবা একসাথে একটা বিখ্যাত গল্প খুঁজে বের করার কথা বলেছিলাম... ...যেটাকে ঈশ্বরের কাছে প্রার্থনা করা হয়েছে... ...এবং বলবে তুমি সিংহাসন খুঁজে পাবে না, সাধুরা চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏شَهْرٍ ‏ ‏قَالَ ‏ ‏لَقِينَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏وَنَحْنُ نُرِيدُ ‏ ‏الطُّورَ ‏ ‏فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُشَدُّ ‏ ‏الْمَطِيُّ ‏ ‏إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏وَمَسْجِدِ الْمَدِينَةِ ‏ ‏وَبَيْتِ الْمَقْدِسِ ‏","","",""],[11450,11450,"","আমার বাবা একজন উত্তম ভাই ছিলেন, তিনি তার নির্দেশনার জন্য প্রার্থনা করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْعَزْلِ ‏ ‏فَقَالَ ‏ ‏لَيْسَ مِنْ كُلِّ ‏ ‏الْمَاءِ ‏ ‏يَكُونُ الْوَلَدُ إِذَا أَرَادَ اللَّهُ أَنْ يَخْلُقَ شَيْئًا لَمْ يَمْنَعْهُ شَيْءٌ ‏","","",""],[11451,11451,"","আমরা ভিড়ের কথা বলেছিলাম, আমরা কথা বললাম, ঈশ্বর তাকে প্রার্থনা করেছিলেন আর সে এমন একজন লোককে ফিরিয়ে আনবে না যে তার ওপর বিশ্বাস করে, ঈশ্বর এবং অন্য একদিন তাকে রক্ষা করবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏وَهَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُبْغِضُ ‏ ‏الْأَنْصَارَ ‏ ‏رَجُلٌ يُؤْمِنُ بِاللَّهِ وَرَسُولِهِ ‏ ‏وَقَالَ ‏ ‏هَاشِمٌ ‏ ‏يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏","","",""],[11452,11452,"","আমরা বাবার কৌতুকের সবচেয়ে ভাল কথা বলেছিলাম, লর্ডের কাছে প্রার্থনা করতো যদি সে তোমাকে মেরে ফেলে তাহলে সে আর তার ভাইকে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَاتَلَ أَحَدُكُمْ أَخَاهُ فَلْيَجْتَنِبْ الْوَجْهَ ‏","","",""],[11453,11453,"","আমি ঈশ্বরের কাছে তার জন্য প্রার্থনা করার আদেশ দিয়েছিলাম আর তিনি যদি যেতে চান, তাহলে আমি আপনাকে একা ছেড়ে যাব না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏لَا نَتْرُكَ أَحَدًا يَمُرُّ بَيْنَ أَيْدِينَا فَإِنْ أَبَى إِلَّا أَنْ نَدْفَعَهُ ‏ ‏أَوْ نَحْوَ هَذَا ‏","","",""],[11454,11454,"","আমরা ঈশ্বরের সর্বোচ্চ এবং রাগ নিয়ে খেলা করেছি। তিনি বলেছিলেন, আমি আমার বাবার চেয়ে ভাল কাজ করব, অবশেষে আমার লর্ডের কাছে খুশি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏اخْتِنَاثِ ‏ ‏الْأَسْقِيَةِ ‏","","",""],[11455,11455,"","আমরা আমার বাবার সবচেয়ে ভালো, মজা করে খুশি হলাম। সে ঈশ্বরের কাছে প্রার্থনা করে এবং আপনার মনে মনে মনে তার হাত ঢুকিয়ে দেয় যে, আপনি তার হাতে হাত রেখে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَضَعْ يَدَهُ عَلَى ‏ ‏فِيهِ فَإِنَّ الشَّيْطَانَ يَدْخُلُ مَعَ التَّثَاؤُبِ ‏","","",""],[11456,11456,"","আমি তাদের বলেছি তারা তাদের কাছে জিজ্ঞেস করেনি আমি তার হাতে সব কিছু হারাচ্ছি আর গান গাওয়া ছাড়া সেটা উড়িয়ে দেবার জন্য আমাদের যা আছে তা হল, কে ভাল, ভাল হচ্ছে আমাদের ভালো উপহার বা অনেক সময় উপহার দেবে না। আমার বাবার প্রতারণা নিয়ে কথা বলার জন্য একটা ছেলেকে আরো বেশি কথা বলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏جَاءَ نَاسٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَسَأَلُوهُ فَأَعْطَاهُمْ قَالَ فَجَعَلَ لَا يَسْأَلُهُ أَحَدٌ مِنْهُمْ إِلَّا أَعْطَاهُ حَتَّى نَفِدَ مَا عِنْدَهُ فَقَالَ لَهُمْ حِينَ أَنْفَقَ كُلَّ شَيْءٍ بِيَدِهِ ‏ ‏وَمَا يَكُونُ عِنْدَنَا مِنْ خَيْرٍ فَلَنْ نَدَّخِرَهُ عَنْكُمْ وَإِنَّهُ مَنْ يَسْتَعْفِفْ يُعِفَّهُ اللَّهُ وَمَنْ يَسْتَغْنِ يُغْنِهِ اللَّهُ وَمَنْ يَتَصَبَّرْ يُصَبِّرْهُ اللَّهُ وَلَنْ تُعْطَوْا عَطَاءً خَيْرًا أَوْسَعَ مِنْ الصَّبْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَالِكَ بْنَ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏فَذَكَرَ مِثْلَ مَعْنَاهُ ‏","","",""],[11457,11457,"","আমার বাবা, আমার প্রিয়তম বাবা, আমার প্রিয়তম বাবা, ঈশ্বরের কাছে প্রার্থনা করেছিলাম । তারা ছুরিটা দেখে মনে রাখবে, এই আকাশ পাপ থেকে ক্ষমা করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اجْتَمَعَ قَوْمٌ يَذْكُرُونَ اللَّهَ إِلَّا حَفَّتْهُمْ الْمَلَائِكَةُ وَتَغَشَّتْهُمْ الرَّحْمَةُ وَنَزَلَتْ عَلَيْهِمْ السَّكِينَةُ وَذَكَرَهُمْ اللَّهُ فِيمَنْ عِنْدَهُ وَقَالَ إِنَّ اللَّهَ يُمْهِلُ حَتَّى إِذَا كَانَ ثُلُثُ اللَّيْلِ الْآخِرُ نَزَلَ اللَّهُ عَزَّ وَجَلَّ إِلَى هَذِهِ السَّمَاءِ فَنَادَى هَلْ مِنْ مُذْنِبٍ يَتُوبُ هَلْ مِنْ مُسْتَغْفِرٍ هَلْ مِنْ دَاعٍ هَلْ مِنْ سَائِلٍ إِلَى الْفَجْرِ ‏","","",""],[11458,11458,"","আমি আমার বাবার জন্য সবচেয়ে ভালো মানুষ সম্পর্কে কথা বলেছি, তার কাছে প্রার্থনা করেছে এবং সে ঈশ্বরের কাছে প্রার্থনা করেছে, আমি যেন নিজের হাত ধরে রাখতে না পারি। আমাকে হাল ছেড়ে দিতে হবে কিভাবে আমরা এখন আছি। আমরা যা করছি তার প্রতি ঈর্ষার কারণে আমি ক্লান্ত, লর্ড তাকে হত্যা করেছে এবং নবীকে মন্ত্র নিতে হয়েছে. তারা এটা খেয়ে খুশি যে মার্বেল কিভাবে ব্যাখ্যা করতে হয়.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏وَضَعَ رَجُلٌ يَدَهُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَاللَّهِ مَا أُطِيقُ أَنْ أَضَعَ يَدِي عَلَيْكَ مِنْ شِدَّةِ حُمَّاكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا مَعْشَرَ الْأَنْبِيَاءِ ‏ ‏يُضَاعَفُ لَنَا ‏ ‏الْبَلَاءُ ‏ ‏كَمَا يُضَاعَفُ لَنَا الْأَجْرُ إِنْ كَانَ النَّبِيُّ مِنْ الْأَنْبِيَاءِ ‏ ‏يُبْتَلَى ‏ ‏بِالْقُمَّلِ حَتَّى يَقْتُلَهُ وَإِنْ كَانَ النَّبِيُّ مِنْ الْأَنْبِيَاءِ ‏ ‏لَيُبْتَلَى ‏ ‏بِالْفَقْرِ حَتَّى يَأْخُذَ الْعَبَاءَةَ ‏ ‏فَيَخُونَهَا ‏ ‏وَإِنْ كَانُوا لَيَفْرَحُونَ ‏ ‏بِالْبَلَاءِ ‏ ‏كَمَا تَفْرَحُونَ بِالرَّخَاءِ ‏","","",""],[11459,11459,"","আমি আমার ভাইয়ের সঙ্গে আরও ভাল হওয়ার চেষ্টা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا عَجِلَ أَحَدُكُمْ أَوْ ‏ ‏أَقْحَطَ ‏ ‏فَلَا يَغْتَسِلَنَّ ‏","","",""],[11460,11460,"","আমরা বাবার ভালোর জন্য বাবার ভালবাসা সম্পর্কে কথা বলেছি, এই কৌশল সে ঈশ্বরের বংশধরদের নাকে কাদার সৃষ্টি করেছে এবং তারা এই ভয়াবহ প্রভাবের দ্বারা উদ্ধার করেছে। সূর্য, রাত্রি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ ‏ ‏رَأَى الطِّينَ فِي أَنْفِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَرْنَبَتِهِ ‏ ‏مِنْ أَثَرِ السُّجُودِ وَكَانُوا مُطِرُوا مِنْ اللَّيْلِ ‏","","",""],[11461,11461,"","আমি আমার বাবা কিভাবে ক্ষমার শান্তির কথা বলেছিলেন, ঐ ড্রাগ বলেছিল যে আপনি তার ভুলের জন্য ঈশ্বরকে পাঠাতে বন্ধ করবেন। গোপন তথ্য আপনারা সবাই পাবেন যে আপনারা সবাই নন। তিনি প্রার্থনায় বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اعْتَكَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَسَمِعَهُمْ يَجْهَرُوا بِالْقِرَاءَةِ وَهُوَ فِي قُبَّةٍ لَهُ فَكَشَفَ السُّتُورَ ‏ ‏وَكَشَفَ ‏ ‏وَقَالَ ‏ ‏أَلَا كُلُّكُمْ ‏ ‏مُنَاجٍ رَبَّهُ فَلَا يُؤْذِيَنَّ بَعْضُكُمْ بَعْضًا وَلَا يَرْفَعَنَّ بَعْضُكُمْ عَلَى ‏ ‏بَعْضٍ فِي الْقِرَاءَةِ ‏ ‏أَوْ قَالَ فِي الصَّلَاةِ ‏","","",""],[11462,11462,"","আমি আমার বাবার জন্য সবচেয়ে ভাল ব্যক্তি সম্বন্ধে কথা বলেছিলাম । আর একবার সে তার মৃত্যুর মুখ দিয়ে বলতে বলল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَتَّبِعُنَّ سُنَنَ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ حَتَّى لَوْ دَخَلَ رَجُلٌ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏جُحْرَ ضَبٍّ لَتَبِعْتُمُوهُمْ فِيهِ ‏ ‏وَقَالَ مَرَّةً لَتَبِعْتُمُوهُ فِيهِ ‏","","",""],[11463,11463,"","আমি বাবার সবচেয়ে ভালোটা নিয়ে কথা বলেছি, আমার বাবার কাছে প্রার্থনা করার জন্য ঈশ্বর কখনো তার কাছে প্রার্থনা করবেন না আর তিনি আত্মসমর্পণ করবেন যদি তিনি আগুন থেকে রক্ষা পান, এবং আগুন থেকে রক্ষা পেতে। ঋণের কারণে হয়তো তাদের ভয়ে আটকে থাকতে পারে, তারা আমাদের সাথে প্রার্থনা করবে এবং আমাদের সাথে লড়াই করবে, আর তারা চলে যাবে। তারা বেরিয়ে আসবে আর বলবে আমরা এখান থেকে বের হয়ে যাবো। বাবা যেভাবে মনে করেছিলেন, তাতে বাবা খুশি হবেন । আমি ভয় পাই, ঈশ্বর শপথ করিবেন, তিনি বলেন, তাহাদিগকে অগ্নি দ্বারা হতিত করা যাইবে, কিম্বা কহিল যে, তাহারা কখনও কোন জাদু করে নাই । ভয় পাওয়াটা হবে ভালোবাসার সবচেয়ে ভয়ঙ্কর, খোদার কসম, ওরা যদি ভেতরে ঢুকতেই পারে, তাহলে ওরা ওদেরকে মেরে ফেলবে। অন্য কিছু.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَلَصَ الْمُؤْمِنُونَ مِنْ النَّارِ يَوْمَ الْقِيَامَةِ وَأَمِنُوا فَمَا مُجَادَلَةُ أَحَدِكُمْ لِصَاحِبِهِ فِي الْحَقِّ يَكُونُ لَهُ فِي الدُّنْيَا بِأَشَدَّ مُجَادَلَةً لَهُ مِنْ الْمُؤْمِنِينَ لِرَبِّهِمْ فِي إِخْوَانِهِمْ الَّذِينَ أُدْخِلُوا النَّارَ قَالَ يَقُولُونَ رَبَّنَا إِخْوَانُنَا كَانُوا يُصَلُّونَ مَعَنَا وَيَصُومُونَ مَعَنَا وَيَحُجُّونَ مَعَنَا فَأَدْخَلْتَهُمْ النَّارَ قَالَ فَيَقُولُ ‏ ‏اذْهَبُوا فَأَخْرِجُوا مَنْ عَرَفْتُمْ فَيَأْتُونَهُمْ فَيَعْرِفُونَهُمْ بِصُوَرِهِمْ لَا تَأْكُلُ النَّارُ صُوَرَهُمْ فَمِنْهُمْ مَنْ أَخَذَتْهُ النَّارُ إِلَى أَنْصَافِ سَاقَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى كَعْبَيْهِ فَيُخْرِجُونَهُمْ فَيَقُولُونَ رَبَّنَا أَخْرَجْنَا مَنْ أَمَرْتَنَا ثُمَّ يَقُولُ أَخْرِجُوا مَنْ كَانَ فِي قَلْبِهِ وَزْنُ دِينَارٍ مِنْ الْإِيمَانِ ثُمَّ مَنْ كَانَ فِي قَلْبِهِ وَزْنُ نِصْفِ دِينَارٍ حَتَّى يَقُولَ مَنْ كَانَ فِي قَلْبِهِ ‏ ‏مِثْقَالُ ‏ ‏ذَرَّةٍ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَمَنْ لَمْ يُصَدِّقْ بِهَذَا فَلْيَقْرَأْ هَذِهِ الْآيَةَ ‏ { ‏إِنَّ اللَّهَ لَا يَظْلِمُ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا ‏} ‏قَالَ فَيَقُولُونَ رَبَّنَا قَدْ أَخْرَجْنَا مَنْ أَمَرْتَنَا فَلَمْ يَبْقَ فِي النَّارِ أَحَدٌ فِيهِ خَيْرٌ قَالَ ثُمَّ يَقُولُ اللَّهُ شَفَعَتْ الْمَلَائِكَةُ وَشَفَعَ الْأَنْبِيَاءُ وَشَفَعَ الْمُؤْمِنُونَ وَبَقِيَ أَرْحَمُ الرَّاحِمِينَ قَالَ فَيَقْبِضُ قَبْضَةً مِنْ النَّارِ ‏ ‏أَوْ قَالَ قَبْضَتَيْنِ ‏ ‏نَاسٌ لَمْ يَعْمَلُوا لِلَّهِ خَيْرًا قَطُّ قَدْ احْتَرَقُوا حَتَّى صَارُوا حُمَمًا قَالَ فَيُؤْتَى بِهِمْ إِلَى مَاءٍ يُقَالُ لَهُ مَاءُ الْحَيَاةِ فَيُصَبُّ عَلَيْهِمْ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ فَيَخْرُجُونَ مِنْ ‏ ‏أَجْسَادِهِمْ مِثْلَ اللُّؤْلُؤِ فِي أَعْنَاقِهِمْ الْخَاتَمُ عُتَقَاءُ اللَّهِ قَالَ فَيُقَالُ لَهُمْ ادْخُلُوا الْجَنَّةَ فَمَا تَمَنَّيْتُمْ ‏ ‏أَوْ رَأَيْتُمْ ‏ ‏مِنْ شَيْءٍ فَهُوَ لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا قَالَ فَيَقُولُونَ رَبَّنَا وَمَا أَفْضَلُ مِنْ ذَلِكَ قَالَ فَيَقُولُ رِضَائِي عَلَيْكُمْ فَلَا أَسْخَطُ عَلَيْكُمْ أَبَدًا ‏","","",""],[11464,11464,"","সেই কৌশল ঈশ্বরের কাছে প্রার্থনা করে বলে যে, তা শিখতে ও সেই তিনজনের অগণিত স্বপ্নের বিষয়ে শিখতে হবে । মানুষের খোঁজে সে চেষ্টা করার আগেই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمُلَامَسَةِ ‏ ‏وَالْمُلَامَسَةُ يُمَسُّ الثَّوْبُ لَا يُنْظَرُ إِلَيْهِ ‏ ‏وَعَنْ الْمُنَابَذَةِ ‏ ‏وَهُوَ طَرْحُ الثَّوْبِ الرَّجُلُ بِالْبَيْعِ قَبْلَ أَنْ يُقَلِّبَهُ وَيَنْظُرَ إِلَيْهِ ‏","","",""],[11465,11465,"","আমি সবচেয়ে ভাল কিছুর মধ্যে সর্বোত্তমটা সম্বন্ধে কথা বলেছিলাম । গ্রীষ্মের নামাজের পর সূর্য আর প্রার্থনা নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ الْجُنْدَعِيِّ ‏ ‏سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏حَتَّى تَرْتَفِعَ الشَّمْسُ ‏ ‏وَلَا صَلَاةَ بَعْدَ صَلَاةِ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ ‏","","",""],[11466,11466,"","আমরা একটা বড় ছেলের সঙ্গে খেলা করার চেষ্টা করেছিলাম, যেটা বলেছিল যে আমরা আমার ভাই হয়েছি । ভাই, সকাল থেকে প্রার্থনা শেষে কোন প্রার্থনা না করে সূর্যকে উঠিয়ে দেয়, প্রার্থনাটাও অজ্ঞান হয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ أَبِي عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عِيَاضٍ ‏ ‏وَعَطَاءِ بْنِ بُخْتٍ ‏ ‏كِلَاهُمَا يُخْبِرُ ‏ ‏عُمَرَ بْنَ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُمَا سَمِعَاهُ يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَقُولُ ‏ ‏لَا صَلَاةَ بَعْدَ صَلَاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ وَلَا صَلَاةَ بَعْدَ صَلَاةِ الْعَصْرِ حَتَّى اللَّيْلِ ‏","","",""],[11467,11467,"","আমরা একটি আনন্দের মোড়ের কথা বলেছিলাম। তিনি বললেন, তিনি তার জন্য প্রার্থনা করবেন এবং তিনি পতাকা ছেড়ে দিবেন এবং তার হাতে টাকা ঢুকিয়ে দিবেন। আমাদের সময় তিনি কথা বলেছেন, আমি বেনের ছেলেদের সাথে কথা বলেছি তিনি আমাকে বলেছেন তিনি আমাকে বলেছেন তিনি আমাকে বলতে চেয়েছিলেন তিনি আমাকে দুঃখ আর বড় ছেলের বড় ছেলে হিসাবে ভাল কাজ করেছেন কুকুর ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ ثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْمُلَامَسَةِ ‏ ‏وَالْمُلَامَسَةُ لَمْسُ الثَّوْبِ لَا يُنْظَرُ إِلَيْهِ وَعَنْ ‏ ‏الْمُنَابَذَةِ ‏ ‏وَالْمُنَابَذَةُ طَرْحُ الرَّجُلِ ثَوْبَهُ إِلَى الرَّجُلِ قَبْلَ أَنْ يُقَلِّبَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ الْجُنْدَعِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏يَعْنِي مِثْلَ حَدِيثِ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏وَابْنِ بَكْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏وَقَالَ حَتَّى تَرْتَفِعَ الشَّمْسُ ‏","","",""],[11468,11468,"","আমরা আমার ভাইয়ের গালের গাল নিয়ে কথা বলেছি, সে ঈশ্বরের কাছে দু বছর ধরে প্রার্থনা করছে, আর একজন নেকড়েকে তার দুর্দশার মধ্যে রেখেছে। ( হিতোপদেশ ১৪: ২২) তার দুর্দশার দ্বারা পূর্ণ হয় ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لِبْسَتَيْنِ وَعَنْ بَيْعَتَيْنِ أَمَّا اللِّبْسَتَانِ فَاشْتِمَالُ ‏ ‏الصَّمَّاءِ ‏ ‏أَنْ يَشْتَمِلَ فِي ثَوْبٍ وَاحِدٍ يَضَعَ طَرَفَيْ الثَّوْبِ عَلَى عَاتِقِهِ الْأَيْسَرِ وَيَتَّزِرَ بِشِقِّهِ الْأَيْمَنِ وَالْأُخْرَى أَنْ يَحْتَبِيَ فِي ثَوْبٍ وَاحِدٍ لَيْسَ عَلَيْهِ غَيْرُهُ وَيُفْضِيَ بِفَرْجِهِ إِلَى السَّمَاءِ وَأَمَّا الْبَيْعَتَانِ فَالْمُنَابَذَةُ وَالْمُلَامَسَةُ ‏ ‏وَالْمُنَابَذَةُ أَنْ يَقُولَ إِذَا نَبَذْتَ هَذَا الثَّوْبَ فَقَدْ وَجَبَ الْبَيْعُ ‏ ‏وَالْمُلَامَسَةُ أَنْ يَمَسَّهُ بِيَدِهِ وَلَا يَلْبَسَهُ وَلَا يُقَلِّبَهُ إِذَا مَسَّهُ وَجَبَ الْبَيْعُ ‏","","",""],[11469,11469,"","আমি সবচেয়ে ভালো কথা বলেছি আর বললাম বিদ্রোহীদের কথা। আমার বাবা একজন সাহসী মানুষ যে তার কাছে প্রার্থনা করেছে আর বলেছে সে আমাকে ফোন করেছে, আমি দুঃখিত, তুমি কখনো যাওনি। ব্যর্থ হলে ব্যর্থ হবে না। আর আমরা তোমার সাথে ঝগড়া করতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَقَالَ قَالَ ‏ ‏الثَّوْرِيُّ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَنَّ ‏ ‏الْأَغَرَّ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏وَأَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ يُنَادِي مُنَادٍ ‏ ‏أَنَّ لَكُمْ أَنْ تَحْيَوْا فَلَا تَمُوتُوا أَبَدًا وَأَنَّ لَكُمْ أَنْ تَصِحُّوا فَلَا ‏ ‏تَسْقَمُوا ‏ ‏أَبَدًا وَأَنَّ لَكُمْ أَنْ تَشِبُّوا وَلَا ‏ ‏تَهْرَمُوا ‏ ‏وَأَنَّ لَكُمْ أَنْ تَنْعَمُوا وَلَا تَبْأَسُوا أَبَدًا فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ ‏ { ‏وَنُودُوا أَنْ تِلْكُمْ الْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ ‏}","","",""],[11470,11470,"","আমি আমার ভাইয়ের সবচেয়ে ভালো কথা বলেছি, সে তার কথা শোনে, সে তার জন্য প্রার্থনা করে এবং সে বলছে যতক্ষণ না পর্যন্ত সে সেবা করবে না তার সেবা করবে, ততক্ষণ পর্যন্ত না সে তাকে খুন করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَقْتَتِلَ فِئَتَانِ عَظِيمَتَانِ دَعْوَاهُمَا وَاحِدَةٌ ‏ ‏تَمْرُقُ ‏ ‏بَيْنَهُمَا ‏ ‏مَارِقَةٌ ‏ ‏يَقْتُلُهَا أَوْلَاهُمَا بِالْحَقِّ ‏","","",""],[11471,11471,"","আমি আমার ভাইয়ের সঙ্গে সাহায্য করার বিষয়ে কথা বলেছিলাম । এমনকি খরচ করার জন্য অথবা বলা হয়েছে কি ঘটেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا كَانَ فِي مُصَلَّاهُ يَنْتَظِرُ الصَّلَاةَ تَقُولُ الْمَلَائِكَةُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ حَتَّى يَنْصَرِفَ أَوْ ‏ ‏يُحْدِثَ ‏ ‏فَقُلْتُ مَا ‏ ‏يُحْدِثُ ‏ ‏فَقَالَ كَذَا قُلْتُ ‏ ‏لِأَبِي سَعِيدٍ ‏ ‏فَقَالَ ‏ ‏يَفْسُو أَوْ يَضْرِطُ ‏","","",""],[11472,11472,"","আমরা বাপ্তিস্ম নিয়ে কথা বলেছি কিন্তু বাবাকে সাহায্য করতে চেয়েছিলাম আমি ভালো ছেলের সাথে খুশি হয়েছি। আমি জানি না যে আমি একটা ছেলে হয়ে গেলে তুমি জেগে উঠবে আর তুমি আমাদের শেষ করে দিবে। আমাদের প্রতি ভালোবাসা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الصَّهْبَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏لَا أَعْلَمُهُ إِلَّا رَفَعَهُ ‏ ‏قَالَ ‏ ‏إِذَا أَصْبَحَ ابْنُ ‏ ‏آدَمَ ‏ ‏فَإِنَّ أَعْضَاءَهُ تُكَفِّرُ لِلِّسَانِ تَقُولُ اتَّقِ اللَّهَ فِينَا فَإِنَّكَ إِنْ اسْتَقَمْتَ اسْتَقَمْنَا وَأَنْ ‏ ‏اعْوَجَجْتَ ‏ ‏اعْوَجَجْنَا ‏","","",""],[11473,11473,"","আমি আমার বাবা আমাকে সাহায্য করার কথা বলেছিলাম, আল্লাহ আপনার কাজ শুরু করছেন, আপনি এটা নিয়ে মজা করছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنْتَ تَخْلُقُهُ أَنْتَ تَرْزُقُهُ فَأَقْرِرْهُ مَقَرَّهُ فَإِنَّمَا كَانَ قَدَرٌ ‏","","",""],[11474,11474,"","ঈশ্বর এটিকে উদ্ধার করতে এবং বধির মৌসুম ও কষ্টেরতার জন্য আত্মসমর্পণ করতে হবে । গ্রীষ্মের দুই ঘন্টার মধ্যে মাত্র তিনজন প্রার্থনা করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صِيَامِ يَوْمَيْنِ يَوْمِ الْفِطْرِ وَيَوْمِ الْأَضْحَى وَعَنْ لِبْسَتَيْنِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ وَعَنْ صَلَاةٍ فِي سَاعَتَيْنِ بَعْدَ الصُّبْحِ وَبَعْدَ الْعَصْرِ ‏","","",""],[11475,11475,"","আমরা একটা ভাল শপথ নিয়ে কথা বলেছিলাম আর তারপর আমার ছেলেকে হত্যা করার ব্যাপারে আমরা উত্তেজিত হয়ে গিয়েছিলাম । তাকে অসুস্থ হতে বাধা দিল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏وَيَرْفَعُ يَدَيْهِ هَكَذَا يَجْعَلُ ظَاهِرَهُمَا فَوْقَ وَبَاطِنَهُمَا أَسْفَلَ ‏ ‏وَوَصَفَ ‏ ‏حَمَّادٌ ‏ ‏وَرَفَعَ ‏ ‏حَمَّادٌ ‏ ‏يَدَيْهِ وَكَفَّيْهِ مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[11476,11476,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি সেই কথাগুলো তুলে ধরেছেন, যেগুলো আপনার একজন শয়তান এবং তার ইচ্ছার সঙ্গে মিল রেখে তার প্রার্থনার প্রতি আগ্রহী । সে বলেছিল সে হয়তো কোন কথা শুনবে না, কিংবা ভালো কাউকে খুঁজে পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ وَهُوَ فِي صَلَاتِهِ فَيَأْخُذُ شَعْرَةً مِنْ ‏ ‏دُبُرِهِ ‏ ‏فَيَمُدُّهَا فَيَرَى أَنَّهُ قَدْ ‏ ‏أَحْدَثَ ‏ ‏فَلَا يَنْصَرِفَنَّ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[11477,11477,"","আমরা আমাদের বাপ্তিস্মের কথা বলেছি কিন্তু আমার বাবার একটা ছেলে আছে। ঈশ্বরের কাছে প্রার্থনা করা উচিত। তার ঋণ থেকে তাকে দেখা যাবে। সে শুনতে পাবে, নাহলে সে খুঁজে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ وَهُوَ فِي صَلَاتِهِ فَيَأْخُذُ ‏ ‏بِشَعْرَةٍ ‏ ‏مِنْ ‏ ‏دُبُرِهِ ‏ ‏فَيَمُدُّهَا فَيَرَى أَنَّهُ قَدْ ‏ ‏أَحْدَثَ ‏ ‏فَلَا يَنْصَرِفْ حَتَّى يَسْمَعَ صَوْتًا أَوْ يَجِدَ رِيحًا ‏","","",""],[11478,11478,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম, আমার ভাইকে সাহায্য করার বিষয়ে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَبْعَثَنَّ اللَّهُ عَزَّ وَجَلَّ فِي هَذِهِ الْأُمَّةِ خَلِيفَةً ‏ ‏يَحْثِي ‏ ‏الْمَالَ ‏ ‏حَثْيًا ‏ ‏وَلَا يَعُدُّهُ عَدًّا ‏","","",""],[11479,11479,"","আমার বাবার জীবিত বন্ধু সেই পবিত্র অ্যানের পড়ায় খুশি হয় এবং এটাকে একটাও বলে ডাকে । আল্লাহ বলবে, যখন সে তাকে দেখে ফেলবে যে আমরা তাকে খুন করতাম না, সে আমাদের সাথে বসে বলত, সে তোমাকে জেব্রার সাথে নিয়ে পালিয়ে যেতে বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي مُزَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُمْ ‏ ‏كَانُوا جُلُوسًا يَقْرَءُونَ الْقُرْآنَ وَيَدْعُونَ قَالَ فَخَرَجَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا رَأَيْنَاهُ سَكَتْنَا فَقَالَ أَلَيْسَ كُنْتُمْ تَصْنَعُونَ كَذَا وَكَذَا قُلْنَا نَعَمْ قَالَ فَاصْنَعُوا كَمَا كُنْتُمْ تَصْنَعُونَ وَجَلَسَ مَعَنَا ثُمَّ قَالَ ‏ ‏أَبْشِرُوا ‏ ‏صَعَالِيكَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏بِالْفَوْزِ يَوْمَ الْقِيَامَةِ عَلَى الْأَغْنِيَاءِ بِخَمْسِ مِائَةٍ أَحْسَبُهُ قَالَ سَنَةً ‏","","",""],[11480,11480,"","আমরা বাবার ছেলের কথা বলেছিলাম, তার বাবার দয়া থেকে আমাকে সাহায্য করার জন্য ঈশ্বর আছেন আর তিনি বলবেন যদি তুমি তোমার হাতে পা দাও... ...তাহলে সে তাকে তোমার হাতে তুলে দিবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيُمْسِكْ يَدَهُ عَلَى ‏ ‏فِيهِ فَإِنَّ الشَّيْطَانَ يَدْخُلُ ‏","","",""],[11481,11481,"","আমরা বাবার বাপ্তিস্মের কথা বলেছিলাম, সে আমার ভাইয়ের সাথে লড়াই করার চেষ্টা করছিল, ঈশ্বর তাকে জানেন আর তার গলা কেটে ফেলবে যতক্ষণ না সে তাদের ধরা পড়ে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏بِشْرُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏ ‏فِي الصَّوْمِ فَلَمْ يَزَلْ بِهِ أَصْحَابُهُ حَتَّى رَخَّصَ لَهُمْ مِنْ ‏ ‏السَّحَرِ ‏ ‏إِلَى ‏ ‏السَّحَرِ ‏","","",""],[11482,11482,"","আমরা একটা রাজহাঁস থেকে মুক্তি পাওয়ার চেষ্টা করেছি বলে বলেছিলাম। ঈশ্বর, এই কৌশলটা হচ্ছে, ছুরি আর দুঃখের হলে লড়াই করা আর আল্লাহ এসে বললেন, তার কাছে সিঁড়ি আছে। আর সে তার বাবা-মা'র জন্য এক বছর গান গায় আর সে আমাদের কাছে চলে গেছে। যখন গান গাইবো, তখন গান গাইতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏افْتَخَرَ أَهْلُ الْإِبِلِ وَالْغَنَمِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْفَخْرُ ‏ ‏وَالْخُيَلَاءُ ‏ ‏فِي أَهْلِ الْإِبِلِ ‏ ‏وَالسَّكِينَةُ ‏ ‏وَالْوَقَارُ فِي أَهْلِ الْغَنَمِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ ‏ ‏يَرْعَى غَنَمًا عَلَى أَهْلِهِ وَبُعِثْتُ أَنَا وَأَنَا أَرْعَى غَنَمًا لِأَهْلِي ‏ ‏بِجِيَادٍ ‏","","",""],[11483,11483,"","আমি তাদের একজনের কাছে গিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ الْغِلَابِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَرْضُ كُلُّهَا مَسْجِدٌ إِلَّا الْحَمَّامَ وَالْمَقْبَرَةَ ‏","","",""],[11484,11484,"","আমরা আমাদের কথাবার্তার বিষয়ে কথা বলেছিলাম এবং একটা ছেলে থাকার জন্য এটা হয়েছিল । আমার কাছে একটার মতো একটা মাল আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَاءَ جِنَازَةً فِي أَهْلِهَا فَتَبِعَهَا حَتَّى يُصَلِّيَ عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ مَضَى مَعَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[11485,11485,"","ঈশ্বর তাঁর শান্তি আছে বলে প্রার্থনা করুন, যার মধ্যে দিয়ে তিনি যে - ত্রাণকর্মীকে হত্যা করেছেন, তাকে অগ্নি দ্বারা নিক্ষেপ করা হবে অথবা খুন.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمْرُقُ ‏ ‏مَارِقَةٌ ‏ ‏عِنْدَ فِرْقَةٍ مِنْ الْمُسْلِمِينَ تَقْتُلُهَا أَوْلَى الطَّائِفَتَيْنِ بِالْحَقِّ ‏","","",""],[11486,11486,"","আমরা আমার বাবা আমাকে সাহায্য করার চেষ্টা করে কথা বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করেন আর আমরা বই পড়তে রাজি হব আর কি সাহায্য করত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏أَمَرَنَا نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَقْرَأَ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَمَا تَيَسَّرَ ‏","","",""],[11487,11487,"","আমরা আমাদের বাপ্তিস্মের বিষয়ে কথা বলেছিলাম কিন্তু আমার ভাইয়ের জন্য আমার ভয় পেয়ে বাবা খুবই ক্লান্ত হয়ে পড়েছিলেন । আমি যা বলছি তা করতে না পেরে কাপুরুষের শোক, আমি খুশি যে আপনারা গেরিলাদের সাথে কথা বলছেন অথবা যে নবীদের কথা শুনেছেন, তা আর হবে না। তাঁর জন্ম হবে না এবং শহরে প্রবেশ করা যাবে না। হয়তো পর্দা থেকে আর যেতে না পারে। তিনি বলেছেন যে হামাদ একটি অফিসে প্রবেশ করেছেন, এমনকি তিনি যদি ক্ষমাও চানও, তাহলে তিনি ক্ষমা চান। আর তাকে তার শান্তি করতে বললে, তুমি ঘুমোবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏حَجَجْنَا فَنَزَلْنَا تَحْتَ ظِلِّ شَجَرَةٍ وَجَاءَ ‏ ‏ابْنُ صَائِدٍ ‏ ‏فَنَزَلَ إِلَى جَنْبِي قَالَ فَقُلْتُ مَا صَبَّ اللَّهُ هَذَا عَلَيَّ فَجَاءَنِي فَقَالَ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏أَمَا ‏ ‏تَرَى مَا أَلْقَى مِنْ النَّاسِ يَقُولُونَ أَنْتَ ‏ ‏الدَّجَّالُ ‏ ‏أَمَا سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏لَا يُولَدُ لَهُ وَلَا يَدْخُلُ ‏ ‏الْمَدِينَةَ ‏ ‏وَلَا ‏ ‏مَكَّةَ ‏ ‏وَقَدْ جِئْتُ الْآنَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَنَا هُوَ ذَا أَذْهَبُ إِلَى ‏ ‏مَكَّةَ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَقَدْ دَخَلَ ‏ ‏مَكَّةَ ‏ ‏وَقَدْ وُلِدَ لِي حَتَّى رَقَقْتُ لَهُ ثُمَّ قَالَ وَاللَّهِ إِنَّ أَعْلَمَ النَّاسِ بِمَكَانِهِ السَّاعَةَ أَنَا فَقُلْتُ ‏ ‏تَبًّا ‏ ‏لَكَ سَائِرَ الْيَوْمِ ‏","","",""],[11488,11488,"","আমি আমার বাবার সঙ্গে সুখী হতে চেয়েছিলাম । বাবা তার উপর দয়া করে, সে মারা গেছে, যখন সে জন্ম নেবে, আমি এক বছরের মধ্যে ক্ষোভ প্রকাশ করতে চাচ্ছি এবং তোমার টাকা জিপার সামনে রেখে না যেতে সাহায্য করব। আমরা একটা মহান কাজ করছি আর এটা আমাদের ভালো কথা বলে দিয়েছে। তিনি বললেন যে হামাদ আমার পক্ষ থেকে মারা গেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْأَعْشَى ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ بُشَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَالَ ثَلَاثَ بَنَاتٍ فَأَدَّبَهُنَّ وَرَحِمَهُنَّ وَأَحْسَنَ إِلَيْهِنَّ فَلَهُ الْجَنَّةُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏مَاتَ ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ يَعْنِي الطَّحَّانَ ‏ ‏وَمَالِكُ بْنُ أَنَسٍ ‏ ‏وَأَبُو الْأَحْوَصِ ‏ ‏وَحَمَّادُ بْنُ زَيْدٍ ‏ ‏فِي سَنَةِ تِسْعٍ وَتِسْعِينَ إِلَّا أَنَّ ‏ ‏مَالِكًا ‏ ‏مَاتَ قَبْلَ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏بِقَلِيلٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَفِي تِلْكَ السَّنَةِ طَلَبْتُ الْحَدِيثَ كُنَّا عَلَى بَابِ ‏ ‏هُشَيْمٍ ‏ ‏وَهُوَ ‏ ‏يُمْلِي عَلَيْنَا إِمَّا قَالَ الْجَنَائِزَ ‏ ‏أَوْ الْمَنَاسِكَ ‏ ‏فَجَاءَ رَجُلٌ بَصْرِيٌّ فَقَالَ مَاتَ ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏رَحْمَةُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ ‏","","",""],[11489,11489,"","আমি আমার কাছে সাহায্যের কথা বলেছিলাম যে ঈশ্বর হয়ত আমাকে বলতে পারবেন আমার বাবা আসবে। বাটন বলছে প্রভুর সিংহাসন বাতিল হয়ে গেছে। আগুনের মধ্যে থাকা অবস্থায় কখনো চোখ বন্ধ করা যায়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏عَنْ الْإِزَارِ فَقَالَ عَلَى الْخَبِيرِ سَقَطْتَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِزْرَةُ الْمُؤْمِنِ إِلَى نِصْفِ السَّاقِ وَلَا حَرَجَ ‏ ‏أَوْ لَا جُنَاحَ ‏ ‏فِيمَا بَيْنَهُ وَبَيْنَ الْكَعْبَيْنِ مَا كَانَ أَسْفَلَ مِنْ الْكَعْبَيْنِ فَهُوَ فِي النَّارِ وَمَنْ جَرَّ إِزَارَهُ بَطَرًا لَمْ يَنْظُرْ اللَّهُ إِلَيْهِ ‏","","",""],[11490,11490,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং এমন একজন ছেলের কাছে প্রার্থনা করেছেন, যিনি কখনো পিপাসার্ত হননি । বেলের পিপাসার জন্য আত্মসমর্পণ করছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِابْنِ صَائِدٍ ‏ ‏مَا ‏ ‏تَرَى قَالَ ‏ ‏أَرَى عَرْشًا عَلَى الْبَحْرِ حَوْلَهُ الْحَيَّاتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاكَ عَرْشُ إِبْلِيسَ ‏","","",""],[11491,11491,"","বাবার ছেলে বাবার সাথে এত ঘনিষ্ঠ হতে যাচ্ছে, বাবার বাবার সাথে আমার বাবার সাথে কথা বলেছি, সে অন্ত্যেষ্টিক্রিয়ার মাধ্যমে চলে গেল, আর আমার বাবা তাকে মেরে ফেলেছিল, রাজকুমার হয়তো জানে যে আমার ছেলে এটা করেছে, তুমি একটা অন্ত্যেষ্টিক্রিয়া বিক্রি করেছ, যতক্ষণ না তুমি এখানে বসে থাক","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏كَانَ جَالِسًا مَعَ ‏ ‏مَرْوَانَ ‏ ‏فَمَرَّتْ جِنَازَةٌ فَمَرَّ بِهِ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقَالَ قُمْ أَيُّهَا الْأَمِيرُ فَقَدْ عَلِمَ هَذَا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا تَبِعَ جِنَازَةً لَمْ يَجْلِسْ حَتَّى تُوضَعَ ‏","","",""],[11492,11492,"","আমরা একে অপরের সাহায্য নিয়ে কথা বলেছি কিন্তু প্রভু ঈশ্বর তাকে প্রার্থনা করেছেন এবং তিনি এগিয়ে গিয়ে এই কল্পনার সমাধান করবেন। যে হাত খুব ভালো বা খারাপ যেতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُسْلِمٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ النَّاجِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ ‏ ‏وَالْبُرُّ ‏ ‏بِالْبُرِّ ‏ ‏وَالشَّعِيرُ بِالشَّعِيرِ وَالتَّمْرُ بِالتَّمْرِ وَالْمِلْحُ بِالْمِلْحِ مِثْلًا بِمِثْلٍ يَدًا بِيَدٍ فَمَنْ زَادَ أَوْ اسْتَزَادَ فَقَدْ أَرْبَى الْآخِذُ وَالْمُعْطِي فِيهِ سَوَاءٌ ‏","","",""],[11493,11493,"","আমরা বাবার ছেলের জন্য কথা বলেছি বাবার সুখের অভিশাপ দিতে। সে আমার বাবার তিন বার চাকরি করবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لِغَنِيٍّ إِلَّا ثَلَاثَةٍ فِي سَبِيلِ اللَّهِ أَوْ ابْنِ السَّبِيلِ أَوْ رَجُلٍ كَانَ لَهُ جَارٌ فَتُصُدِّقَ عَلَيْهِ فَأَهْدَى لَهُ ‏","","",""],[11494,11494,"","বাবার চেয়ে বাবার ভালোর কথা একবারই বলেছিলাম, ভগবানের কাছে প্রার্থনা করতে। সে তাকে চিনেছে আর তার বয়স যখন পাঁচ বা বন্ধুত্ব ছিল তখন তাকে হাতে তুলে দেয়া হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِدْرِيسُ بْنُ يَزِيدَ الْأَوْدِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏صَدَقَةٌ ‏","","",""],[11495,11495,"","দুই মাস ধরে আমরা কথা বলেছি এক বোবার ছেলে, যে কিনা পৃথিবীর রাজার প্রেমে পড়ে আছে। আমার বাবা খুশি যে সে হবে সেই হবে যে বলে। ( খ) কেন আমাদের যিহোবার কাছে প্রার্থনা করা উচিত?","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ فِيمَا دُونَ خَمْسَةِ ‏ ‏أَوْسَاقٍ ‏ ‏مِنْ تَمْرٍ وَلَا حَبٍّ ‏ ‏صَدَقَةٌ ‏","","",""],[11496,11496,"","আমরা ঈশ্বরের দোহাইর অতীত জনের জন্য কথা বলেছি, কিন্তু আমার বাবা সেই লোক হতে পেরে খুশি যে সে-ই হয়েছে আমরা বাইরে গিয়ে জোরে জোরে জোরে অথবা কিছু করতে যেতাম । দূর থেকে আমরা যা যা বলছি তা হল সম্মানের যাজক, বলতে শুনেছি যে আমি ঈশ্বরের প্রেম, আমার ভাইয়ের গোপনীয়তা শুনেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ الْفَرَّاءُ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا نُخْرِجُ ‏ ‏صَدَقَةَ ‏ ‏الْفِطْرِ إِذْ كَانَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ زَبِيبٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ ‏ ‏أَقِطٍ ‏ ‏فَلَمْ نَزَلْ كَذَلِكَ حَتَّى قَدِمَ عَلَيْنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ الْفَرَّاءُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِيَاضَ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي سَرْحٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولُ ‏ ‏كُنَّا نُخْرِجُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[11497,11497,"","আমরা দুই মাস ধরে কথা বলেছি, আমার বাবা বা বাবার সাথে কথা বলার পর। আমার ছেলের সাথে যে শান্তি হয়েছে তা আমার ছেলের জন্য তার আদর্শকে রক্ষা করতে হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هَاشِمٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رِيَاحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ عَنْ غَيْرِهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[11498,11498,"","আমরা যাদের কথা বলেছি তাদের কথা বলছি, তোমার বাবা আমার বাবার জন্য একটা দেবতা সন্তানের জন্ম দিয়েছে। ঐ বদমাশগুলো তার জন্য সবচেয়ে ভাল ভবিষ্যদ্বাণীটা ছিল আর সে উপস্থিত ছিল সে যা বলেছে তা সমর্পণ কর আমরা বলেছিলাম আমরা খেতে পারব না, থামো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَدَّاكِ جَبْرُ بْنُ نَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَصَبْنَا حُمُرًا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَكَانَتْ الْقُدُورُ تَغْلِي بِهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا هَذِهِ فَقُلْنَا حُمُرٌ أَصَبْنَاهَا فَقَالَ وَحْشِيَّةٌ أَوْ أَهْلِيَّةٌ قَالَ قُلْنَا لَا بَلْ أَهْلِيَّةٌ قَالَ ‏ ‏اكْفِئُوهَا قَالَ فَكَفَأْنَاهَا ‏","","",""],[11499,11499,"","আমি বাবার চেয়ে ভাল ভাইয়ের জন্য কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর আমি মানুষের কাছে আসতে চাই... ...যেভাবে সে আমাদের দু’সপ্তাহ কষ্ট দিয়ে মেরেছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِرَجُلٍ فِي ‏ ‏حَدٍّ ‏ ‏قَالَ ‏ ‏فَضَرَبْنَا بِنَعْلَيْنِ أَرْبَعِينَ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أَظُنُّهُ فِي شَرَابٍ ‏","","",""],[11500,11500,"","আমরা আমার বাবার ছেলের জন্য কথা বলেছি ঈশ্বরের ভালোর জন্য আমার প্রাণ দান করার জন্য. সে আত্মসমর্পণ করবে এটা আপনার প্রভুর কিছু কাজ হবে না যে তিনি কখনও না. তার মুখ জয় করতে সক্ষম।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏يَوْمَ يَأْتِي بَعْضُ آيَاتِ رَبِّكَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا ‏} ‏قَالَ ‏ ‏طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا ‏","","",""],[11501,11501,"","আমরা বেনের অভিজাত শ্রেণীর সাথে বসবাসের কথা বলেছি, বাবার খুশি কৌশলের কথা বলেছিলাম, আমি তাদের সাথে কাজ করবো, আর আমি তাদের থেকে কত কিছু করতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْلَ الدَّرَجَاتِ الْعُلَى يَرَاهُمْ مَنْ أَسْفَلَ مِنْهُمْ كَمَا تَرَوْنَ الْكَوْكَبَ الطَّالِعَ فِي الْأُفُقِ مِنْ آفَاقِ السَّمَاءِ وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏مِنْهُمْ وَأَنْعَمَا ‏","","",""],[11502,11502,"","আমরা ছেলেদের কথা বলেছি কিন্তু আমার দাসদের কথা বলেছি, ঈশ্বর কখনো আমাদের অতীত সম্পর্কে হুকুম না করার আদেশ দেন নি। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমি চাই তিনি আমাদের কথা বলতেন। তিনি শুধু ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং তাকে এক উজ্জ্বল হাত দেবেন । এটা নাও তাহলে নিচে নামবে.","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي الْوَدَّاكِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ وَاللَّهِ مَا يَأْتِي عَلَيْنَا أَمِيرٌ إِلَّا وَهُوَ شَرٌّ مِنْ الْمَاضِي وَلَا عَامٌ إِلَّا وَهُوَ شَرٌّ مِنْ الْمَاضِي قَالَ لَوْلَا شَيْءٌ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقُلْتُ مِثْلَ مَا يَقُولُ وَلَكِنْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أُمَرَائِكُمْ أَمِيرًا ‏ ‏يَحْثِي ‏ ‏الْمَالَ ‏ ‏حَثْيًا ‏ ‏وَلَا يَعُدُّهُ عَدًّا يَأْتِيهِ الرَّجُلُ فَيَسْأَلُهُ فَيَقُولُ خُذْ فَيَبْسُطُ الرَّجُلُ ثَوْبَهُ ‏ ‏فَيَحْثِي ‏ ‏فِيهِ وَبَسَطَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِلْحَفَةً ‏ ‏غَلِيظَةً كَانَتْ عَلَيْهِ يَحْكِي صَنِيعَ الرَّجُلِ ثُمَّ جَمَعَ إِلَيْهِ أَكْنَافَهَا قَالَ فَيَأْخُذُهُ ثُمَّ يَنْطَلِقُ ‏","","",""],[11503,11503,"","আমরা এমন কিছু কথা বলেছি যা ভুলে যাওয়ার পর আমাদের সুরক্ষা করা হয়েছে... ...যে জাতি ছিল রাজার মৃত্যুর মৃত্যুর শেষ। তাকে তার আত্মা দিতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَتْ الْأَمَةُ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏لَتَأْخُذُ بِيَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَنْطَلِقُ بِهِ فِي حَاجَتِهَا ‏","","",""],[11504,11504,"","আমরা কথা বলেছি একটা শোকের সাথে একা থাকার জন্য, আমরা একটা ছেলে হয়ে গেছি। সে বলল, সে আছে। সে নাকি আমাকে ছেড়ে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[11505,11505,"","আমরা বলেছিলাম যে, সেই ছেলে যখন লবিতে যেত, তখন আমরা আপনার টাকা ভুলে গিয়েছিলাম, ঈশ্বরের কাছে প্রার্থনা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِزَيْنَبَ ابْنَةِ جَحْشٍ ‏ ‏أَوْلَمَ ‏ ‏قَالَ فَأَطْعَمَنَا خُبْزًا وَلَحْمًا ‏","","",""],[11506,11506,"","আমরা কথা বলেছি কিভাবে আমরা নিঃসঙ্গতা বৃদ্ধি করতে সাহায্য করতে পারি। বিজ্ঞান অজানা এবং মানুষ বলছে মানুষ হলো অকাজের চেয়ে বেশী।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏يَرْفَعُ الْحَدِيثَ قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُرْفَعَ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيَقِلَّ الرِّجَالُ وَيَكْثُرَ النِّسَاءُ حَتَّى يَكُونَ ‏ ‏قَيِّمَ ‏ ‏خَمْسِينَ امْرَأَةً رَجُلٌ وَاحِدٌ ‏","","",""],[11507,11507,"","আমরা তোমার টাকা ভুলে যাওয়ার জন্য হাত বাড়িয়ে বলেছিলাম, ঈশ্বর সেই ছেলেটির ব্যাপারে কিছু করেছেন যে তার জন্য প্রার্থনা করেছে। এক ঠান্ডায় তিনি বলেছিলেন, আমি চাই এটা করা হোক।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏بُرْدَةِ ‏ ‏حِبَرَةٍ ‏ ‏قَالَ أَحْسَبُهُ عَقَدَ بَيْنَ طَرَفَيْهَا ‏","","",""],[11508,11508,"","আমরা এমন লোকেদের জন্য হাত বাড়িয়ে বলেছিলাম, যারা রাত কাটাতে ইচ্ছুক ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَطُوفُ ‏ ‏عَلَى جَمِيعِ نِسَائِهِ فِي لَيْلَةٍ بِغُسْلٍ وَاحِدٍ ‏","","",""],[11509,11509,"","আমরা তাদের সমবেদনা জানাচ্ছি যারা নিজের জন্য ঈশ্বরের জন্য এবং আল্লাহ তাঁর জন্য প্রার্থনা করেছেন এবং তাঁর শান্তির জন্য প্রার্থনা করেছেন। তারা বলেন, আমি আপনাদের কাছ থেকে সুযোগ নিচ্ছি। লুকিয়ে লুকিয়ে থাকো.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏قَالَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[11510,11510,"","আমরা এমন কিছু কথা বলেছি, যার প্রভু আমাদের উচিত ঈশ্বরের পুত্র যে তার দাদার কথা ভুলে গেছে, ঈশ্বর তাকে উদ্ধার করেছেন এবং তাকে আত্মসমর্পণ করবেন যদি আমি লিখতে এবং বলতে পারি","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ عَلَيْكُمْ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏فَقُولُوا وَعَلَيْكُمْ ‏","","",""],[11511,11511,"","আমরা লর্ড লর্ডের লর্ডের লর্ডের সাথে কথা বলেছি, আমার বাবার মত যারা সবচেয়ে ভালো বলবে, ঈশ্বর আপনার ভাইকে ছায়া বা ছায়া দিতে হবে। তুমি তাকে ধরে রাখো এটা করা থেকে তাকে বিরত রাখো.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏أَنَسٍ ‏ ‏وَيُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا قِيلَ يَا رَسُولَ اللَّهِ هَذَا أَنْصُرُهُ مَظْلُومًا فَكَيْفَ أَنْصُرُهُ إِذَا كَانَ ظَالِمًا قَالَ تَحْجُزُهُ تَمْنَعُهُ فَإِنَّ ذَلِكَ نَصْرُهُ ‏","","",""],[11512,11512,"","তিনি একটা মই আছে, আপনি সমুদ্রের অপূর্ব হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏وَإِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السُّحُورِ بَرَكَةً ‏","","",""],[11513,11513,"","আমরা দীর্ঘতম হাত নিয়ে কথা বলেছি... ...আমি তোমার টাকা শুনেছি... ...আমি আমার সর্বোচ্চ চেষ্টা করেছি.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ خَاتَمَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فِضَّةٍ ‏","","",""],[11514,11514,"","আমরা একটি ভাল হাত কথা বলেছি আমরা এটা বলতে পারি না যে ঈশ্বর হয়েছে হয়েছে, তার তিন এবং তিনি ভাল ছিল.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَفِيَّةَ ‏ ‏أَقَامَ عِنْدَهَا ثَلَاثًا وَكَانَتْ ‏ ‏ثَيِّبًا ‏","","",""],[11515,11515,"","আমরা তোমার টাকা ভুলে বরং ভালো একজনের কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তাকে আত্মসমর্পণ করবেন যখন সে আমাদের ধোঁকা দিবে আর সে অবশ্যই আমাকে বলেছে, আর পতনের পরে। বিষটা...","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُهُ يُحَدِّثُ قَالَ ‏ ‏شَهِدْتُ وَلِيمَتَيْنِ مِنْ نِسَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَمَا أَطْعَمَنَا فِيهَا خُبْزًا وَلَا لَحْمًا قَالَ قُلْتُ ‏ ‏فَمَهْ ‏ ‏قَالَ ‏ ‏الْحَيْسَ ‏ ‏يَعْنِي التَّمْرَ ‏ ‏وَالْأَقِطَ ‏ ‏بِالسَّمْنِ ‏","","",""],[11516,11516,"","আমরা আমাদের হত্যা সম্পর্কে কথা বলেছি, আমাদের ঘুরিয়ে বলতে হবে, আমরা একটা ছেলেকে খুজছিলাম যে তোমার টাকা ভুলে গিয়েছিল। সে বলত তুমি তোমার বিখ্যাত আগুন জ্বালিয়ে দিবে না। আলোচনা হবে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَزْهَرُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسْتَضِيئُوا بِنَارِ الْمُشْرِكِينَ وَلَا تَنْقُشُوا خَوَاتِيمَكُمْ عَرَبِيًّا ‏","","",""],[11517,11517,"","আমরা তোমার টাকা নিয়ে ভুলের কথা বলেছিলাম, ঈশ্বর বলেছিলেন, আমি আমার হাতের মধ্যে একটা দাগ শুনতে পাচ্ছি, তাই মেঘ তোমার মায়ের সাথে আমার লবণাক্ততা রয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ ‏ ‏خَشْخَشَةً ‏ ‏بَيْنَ يَدَيَّ فَإِذَا هِيَ ‏ ‏الْغُمَيْصَاءُ بِنْتُ مِلْحَانَ ‏ ‏أُمُّ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏","","",""],[11518,11518,"","আমরা ভয় পেয়েছি যে সোরের মাস্টারকে বলেছিলাম আপনার টাকা ভুলে যেতে যে লর্ড আল্লাহকে রক্ষা করেছেন এবং ক্ষমা করবেন। একজনকে উৎসাহ দেয়া হচ্ছে, যতক্ষণ না পর্যন্ত না তার আত্মা ফিরে আসে। রক্ত হবে, হয়তো তারা এটা জিতে ফেলেছে, অথবা এটা করা সম্ভব না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُسِرَتْ ‏ ‏رَبَاعِيَتُهُ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَشُجَّ ‏ ‏فِي جَبْهَتِهِ حَتَّى سَالَ الدَّمُ عَلَى وَجْهِهِ فَقَالَ ‏ ‏كَيْفَ يُفْلِحُ قَوْمٌ فَعَلُوا هَذَا بِنَبِيِّهِمْ وَهُوَ يَدْعُوهُمْ إِلَى رَبِّهِمْ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏}","","",""],[11519,11519,"","আমরা কথা বলেছি, তোমার টাকা ভুলে যাওয়ার চেয়ে ভালো কিছু করার আছে, একটা জীবন্ত জীবন যাপনের মাধ্যমে তৈরি একটা গ্রীষ্মের আয়োজন করে তার বন্ধুদের দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[11520,11520,"","আমরা একে অপরের সাথে কথা বলেছি, কিন্তু আমার বাবা গর্ভের প্রতিজ্ঞা জয় করতে চান। আমি তাকে বলতে শুনেছি, ঈশ্বর তাকে উদ্ধার করতে হবে এবং তিনি আমাকে ভালবাসা এবং ঈশ্বরের কাছে নিয়ে আসবেন। - একটা ধাঁধা।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏وَعَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏وَحُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُمْ سَمِعُوهُ يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا يَقُولُ ‏ ‏لَبَّيْكَ عُمْرَةً وَحَجًّا لَبَّيْكَ عُمْرَةً وَحَجًّا ‏","","",""],[11521,11521,"","আমি এমন কিছু নিয়ে কথা বলেছিলাম, যা আমি আগে কখনো শুনিনি ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ وَأَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَظُنُّنِي قَدْ سَمِعْتُ مِنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏فَقَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا بَدَنَةٌ قَالَ ارْكَبْهَا مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏","","",""],[11522,11522,"","আমরা কিভাবে নিয়ম মেনে চলার চেষ্টা করেছি আমরা বলেছিলাম যে আপনার টাকা আমরা ভুলে গিয়েছিলাম যে এটা ঈশ্বরের দোহাই ছিল. সে আপনার সাথে ছিল আমি তার পক্ষে মাথা নত করতাম এবং তিনি যদি ফোন করতেন তাহলে তাকে ডাকা হত তার জীবনের সবচেয়ে বড়, সে তাকে পরিচয় দিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي ‏ ‏بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏وَكَانَ يُسَمِّي وَيُكَبِّرُ وَلَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ ‏","","",""],[11523,11523,"","আমরা সোরালের লর্ডের কথা বলেছি, আমাদের বলেছেন যে ঈশ্বর আমাকে যেতে দিবেন না, তিনি ভাববাদীর কাছে প্রার্থনা শুনেছেন, আর তিনি আপনাকে একটি ছেলে দেবেন। তিনি একটা উজ্জ্বল উজ্জ্বল উজ্জ্বল মুখ নিয়ে কথা বলেছেন। আমি তাকে বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, ঈশ্বর তোমাকে একটা উজ্জ্বল রঙ দিতে। আমি আপনাকে বলছি, আমরা যা শুনেছি, তা দেখে ছেলেটি মারা যায় ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏قَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا فَحَدَّثْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏بِذَلِكَ فَقَالَ لَبَّى بِالْحَجِّ وَحْدَهُ فَلَقِيتُ ‏ ‏أَنَسًا ‏ ‏فَحَدَّثْتُهُ بِقَوْلِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَ مَا تَعُدُّونَا إِلَّا صِبْيَانًا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ عُمْرَةً وَحَجًّا ‏","","",""],[11524,11524,"","দুই পুরুষ আত্মসমর্পণ করেছিল, তাদের মধ্যে একজন ছিল খুঁজে পাওয়া গিয়েছিল অথবা বলেছিলেন যে আপনি শেষ একজনকে হত্যা করেছেন। আরেকজন বলেছিলেন যে তিনি ঈশ্বরের অদ্ভুত স্টান্টের উপর বাপ্তিস্ম নিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏حَسِبْتُهُ ‏ ‏قَالَ عَطَسَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلَانِ ‏ ‏فَشَمَّتَ ‏ ‏أَحَدَهُمَا ‏ ‏أَوْ قَالَ ‏ ‏سَمَّتَ ‏ ‏وَتَرَكَ الْآخَرَ فَقِيلَ رَجُلَانِ عَطَسَ أَحَدُهُمَا ‏ ‏فَشَمَّتَّهُ ‏ ‏وَلَمْ ‏ ‏تُشَمِّتْ ‏ ‏الْآخَرَ فَقَالَ ‏ ‏إِنَّ هَذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[11525,11525,"","আমরা কয়েকজনের কথা বলেছি যারা তার জন্য প্রার্থনা করতে হয়েছে এবং তাকে শান্তি দিতে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ أَنْ يَلِيَهُ ‏ ‏الْمُهَاجِرُونَ ‏ ‏وَالْأَنْصَارُ ‏ ‏فِي الصَّلَاةِ ‏","","",""],[11526,11526,"","আমরা কয়েকজনের কথা বলেছি যারা ঈশ্বর তাকে উদ্ধার করতে বলেছেন এবং আপনাকে সাহায্য করতে বলেছেন কিনা। আমি তাকে নিয়ে যাচ্ছি না, আর সে তাকে কষ্ট দিতে দেয় নি।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ فَلْيَأْخُذْهَا وَلْيَمْسَحْ مَا بِهَا مِنْ ‏ ‏الْأَذَى ‏ ‏وَلَا يَدَعْهَا لِلشَّيْطَانِ ‏","","",""],[11527,11527,"","আমরা তাদের সাথে কথা বলেছি যারা বলেছে যে তিনি ঈশ্বরের শান্তির প্রধান ছিলেন না।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمْ يَكُنْ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِحْيَتِهِ عِشْرُونَ شَعَرَةً بَيْضَاءَ ‏ ‏وَخَضَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالْحِنَّاءِ وَالْكَتَمِ ‏ ‏وَخَضَبَ ‏ ‏عُمَرُ ‏ ‏بِالْحِنَّاءِ ‏","","",""],[11528,11528,"","আমি বেশ কয়েকজন লোকের কথা বলেছিলাম যারা বলেছিল যে আমার বাবা ঈশ্বরের জন্য ভাল ছিলেন, তিনি ছিলেন ভুল ।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَجَمَ ‏ ‏أَبُو طَيْبَةَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَاهُ صَاعًا مِنْ طَعَامٍ وَكَلَّمَ أَهْلَهُ فَخَفَّفُوا عَنْهُ ‏","","",""],[11529,11529,"","আমরা কয়েকজনের কথা বলেছি যারা বলেছে যে এটা ঈশ্বরের ইচ্ছা আর শান্তি দান করার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَتَمِّ النَّاسِ صَلَاةً ‏ ‏وَأَوْجَزِهِ ‏","","",""],[11530,11530,"","আমরা আমার বাবার কথা বলেছিলাম তোমাকে ভুলে যেতে, ঈশ্বর প্রতিজ্ঞা করেছেন বেঁচে থাকার জন্য আর আমাদের সময়ের চেয়ে ভাল হতে হবে। আর ঈশ্বরের দোহাই, আমার ছেলে আমাকে বিক্রি করার চেষ্টার মানে হল কষ্ট। একটু একটু করে, আপনার সেই ভাববাদীর কাছে আপনার টাকা প্রার্থনা করেছেন আর আমরা তাকে উদ্ধার করব","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَخْضَرَ بْنَ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَاعَ ‏ ‏قَدَحًا ‏ ‏وَحِلْسًا ‏ ‏فِيمَنْ يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَخْضَرِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏يَعْنِي صَاحِبَ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْأَخْضَرِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ الْحَنَفِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[11531,11531,"","আমরা কথা বলেছিলাম তোমাকে পেয়ে যা করার চেয়ে, ঈশ্বরের কাছে প্রার্থনা করে... ...আর গরমের সময়ে আত্মসমর্পণ করে... ...কিন্তু কেউ না করলে সে তাকে খুঁজে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏غَالِبٌ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي شِدَّةِ الْحَرِّ فَإِذَا لَمْ يَسْتَطِعْ أَحَدُنَا أَنْ يُمَكِّنَ وَجْهَهُ مِنْ الْأَرْضِ ‏ ‏بَسَطَ ‏ ‏ثَوْبَهُ فَيَسْجُدُ عَلَيْهِ ‏","","",""],[11532,11532,"","আমরা আমার ক্লাসের সেরাদের কথা বলেছি... ...এখন আমরা আমার বাবাকে ভুলে যাওয়ার কথা বলেছি, ঈশ্বর শান্তি চুক্তি করেছেন যদি ডিনার করা হয় আর প্রার্থনা করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[11533,11533,"","তিনি বললেন, ঈশ্বর তাঁর জন্য প্রার্থনা করুন এবং তিনি আত্মসমর্পণ করবেন যদি আমি তার প্রার্থনা শুনতে আগ্রহী.","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَعَسَ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيَنْصَرِفْ فَلْيَنَمْ ‏","","",""],[11534,11534,"","আমরা আমার বাবার এক পুত্র পুত্র সন্তানের জন্য চুরি করার চেষ্টা করেছি. আপনার টাকা ঈশ্বরের কাছে প্রার্থনা করেছে এবং যাদের কাছে আমি প্রার্থনা করতে ভুলে গেছি অথবা ঘুমিয়েছি তাদের কাছে প্রার্থনা করতে ভুলে গেছি. তাকে অনেক কষ্ট দিয়েছি.","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏وَيَزِيدَ بْنِ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَسِيَ صَلَاةً أَوْ نَامَ عَنْهَا فَإِنَّمَا كَفَّارَتُهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَكَفَّارَتُهَا أَنْ ‏","","",""],[11535,11535,"","আমি আমার বাবাকে আপনার টাকাপয়সা থেকে সাহায্য করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى ‏ ‏لَيَرْضَى عَنْ الْعَبْدِ أَنْ يَأْكُلَ الْأُكْلَةَ فَيَحْمَدَ اللَّهَ عَزَّ وَجَلَّ عَلَيْهَا أَوْ يَشْرَبَ الشَّرْبَةَ ‏","","",""],[11536,11536,"","আমি বাবার বাবার একমাত্র অনুগ্রহের কথা বলেছি, আমি আমার বাবার সাবেক স্ত্রী, ঈশ্বর এটা করেছেন, আর আমি তা করতে পারব।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَدَمْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعَ سِنِينَ ‏ ‏فَمَا أَعْلَمُهُ قَالَ لِي قَطُّ هَلَّا فَعَلْتَ كَذَا وَكَذَا وَلَا عَابَ عَلَيَّ شَيْئًا قَطُّ ‏","","",""],[11537,11537,"","আমরা কয়েক মাস ধরে বিয়ে করার জন্য দুমাস অপেক্ষা করেছি, আমি এটা করেছি, সে পেয়ে গেছে, সে একটা দর্শনে ফিরে আসবে যা হবে। মুখ বন্ধ রেখে বলছি, নাকটা থরকে বলেছে আমি যেভাবে আদেশ করছি সেভাবে করে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قُلْتُ ‏ ‏أَخْبِرْنِي بِشَيْءٍ ‏ ‏عَقِلْتَهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ صَلَّى الظُّهْرَ يَوْمَ ‏ ‏التَّرْوِيَةِ ‏ ‏قَالَ ‏ ‏بِمِنًى ‏ ‏وَأَيْنَ صَلَّى الْعَصْرَ يَوْمَ ‏ ‏النَّفْرِ ‏ ‏قَالَ ‏ ‏بِالْأَبْطَحِ ‏ ‏قَالَ ثُمَّ قَالَ افْعَلْ كَمَا يَفْعَلُ أُمَرَاؤُكَ ‏","","",""],[11538,11538,"","ঈশ্বর তাকে প্রার্থনা করেছিলেন যেন তিনি তা করার জন্য তার ফোনগুলো রেখে দেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏وَغَسَّانُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَزِيدَ أَبِي مَسْلَمَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ قَالَ ‏ ‏نَعَمْ ‏","","",""],[11539,11539,"","আমরা ঈশ্বরের হাত বা মুখ নিয়ে কথা বলেছি... ...আমি জানি আমরা যা করেছি তা করার জন্য... ...তার জন্য আমি কিছু জানি.","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ الرَّبِيعِ أَبُو خِدَاشٍ الْيُحْمَدِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عِمْرَانَ الْجَوْنِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا أَعْرِفُ شَيْئًا الْيَوْمَ مِمَّا كُنَّا عَلَيْهِ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْنَا لَهُ فَأَيْنَ الصَّلَاةُ قَالَ أَوَلَمْ تَصْنَعُوا فِي الصَّلَاةِ مَا قَدْ عَلِمْتُمْ ‏","","",""],[11540,11540,"","সেই ব্যক্তিকে ক্ষমা করতে হবে","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نَهَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَزَعْفَرَ الرَّجُلُ ‏","","",""],[11541,11541,"","আমরা আপনাদের টাকা নিয়ে জয়ের কথা বলেছিলাম, ঈশ্বরকে বলতে চাই আর তা করতে চাই না । নেকড়েরা আমার জন্য ভাল.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ فَإِنْ كَانَ لَا بُدَّ مُتَمَنِّيَ الْمَوْتِ فَلْيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[11542,11542,"","আমরা কথা বলেছি যারা বলেছে যে ঈশ্বর এটা দিয়েছেন আর এটা পেয়েছে সে বলবে না যে ঈশ্বর আমাকে আশীর্বাদ দেবেন...","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَعَا أَحَدُكُمْ ‏ ‏فَلْيَعْزِمْ ‏ ‏فِي الدُّعَاءِ وَلَا يَقُلْ اللَّهُمَّ إِنْ شِئْتَ فَأَعْطِنِي فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا مُسْتَكْرِهَ لَهُ ‏","","",""],[11543,11543,"","আমরা কথা বলেছি যখন সমবেদনার সাথে আমি মানুষকে জিজ্ঞেস করতাম যে কি বলা উচিত। তিনি বললেন, আমি তাকে ঈশ্বর বলে ডাকতে যাচ্ছি। শেষটি ছিল, আমরা ছিলাম। আমি তাকে ফোন করে ফিরে যেতে চেয়েছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏قَالَ سَأَلَ ‏ ‏قَتَادَةُ ‏ ‏أَنَسًا ‏ ‏أَيُّ دَعْوَةٍ كَانَ أَكْثَرَ يَدْعُو بِهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ أَكْثَرُ دَعْوَةٍ يَدْعُو بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏ ‏وَكَانَ ‏ ‏أَنَسٌ ‏ ‏إِذَا أَرَادَ أَنْ يَدْعُوَ بِدَعْوَةٍ دَعَا بِهَا وَإِذَا أَرَادَ أَنْ يَدْعُوَ بِدُعَاءٍ دَعَا بِهَا فِيهِ ‏","","",""],[11544,11544,"","আমরা তোমার সাথে সেক্সের কথা বলেছি একবার যখন তুমি আমাদের বলেছিলে কিভাবে যুদ্ধ করতে হয়। তোমার টাকা নিয়ে যুদ্ধে যেতে হয়। সে তার প্রার্থনা করতে চায়। অন্ধকার যখন সে তার মুখের উপর আলো দেখে তখন সে তার মুখে আটকে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاذٌ ‏ ‏يَؤُمُّ قَوْمَهُ فَدَخَلَ ‏ ‏حَرَامٌ ‏ ‏وَهُوَ يُرِيدُ أَنْ يَسْقِيَ نَخْلَهُ فَدَخَلَ الْمَسْجِدَ لِيُصَلِّيَ مَعَ الْقَوْمِ فَلَمَّا رَأَى ‏ ‏مُعَاذًا ‏ ‏طَوَّلَ ‏ ‏تَجَوَّزَ ‏ ‏فِي صَلَاتِهِ وَلَحِقَ بِنَخْلِهِ ‏ ‏يَسْقِيهِ فَلَمَّا ‏ ‏قَضَى ‏ ‏مُعَاذٌ ‏ ‏صَلَاتَهُ قِيلَ لَهُ إِنَّ ‏ ‏حَرَامًا ‏ ‏دَخَلَ الْمَسْجِدَ ‏","","",""],[11545,11545,"","আমরা কথা বলেছি যারা বলেছে যে এটা আমার ঈশ্বরের দোহাই আর স্বপ্নের ব্যাপারে। বোকারা বলেছে যে আমি খবর আর খবর নিয়ে ঈশ্বরের কাছে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏الْخَلَاءَ ‏ ‏قَالَ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبَائِثِ ‏","","",""],[11546,11546,"","তিনি যখন বলেন যে লোকেরা এবং আমি তোমাকে উৎসর্গ করেছি, তখন তিনি তোমাকে ত্যাগ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي ‏ ‏بِكَبْشَيْنِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَأَنَا أُضَحِّي بِكَبْشَيْنِ ‏","","",""],[11547,11547,"","আমরা তোমার টাকার উপর জয়ের কথা বলেছি... ...ঈশ্বর বলে যে আমার সাথে এটা ঘটেছে, মুক্তির জন্য নয়, সে শেষ পর্যন্ত এটা পরেনি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَنْ يَلْبَسَهُ فِي الْآخِرَةِ ‏","","",""],[11548,11548,"","আমি তার কথা বলি, তিনি আমাকে তাঁর কথা বলার মাধ্যমে তাকে স্পর্শ করেন । সে তোমার বন্ধু আর বলেছে যে তুমি এটা সক্রিয় করবে যদি এটা চলে যায়.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ وَحَبْلٌ مَمْدُودٌ بَيْنَ ‏ ‏سَارِيَتَيْنِ ‏ ‏فَقَالَ مَا هَذَا قَالُوا ‏ ‏لِزَيْنَبَ ‏ ‏تُصَلِّي فَإِذَا كَسِلَتْ ‏ ‏أَوْ ‏ ‏فَتَرَتْ ‏ ‏أَمْسَكَتْ بِهِ فَقَالَ حُلُّوهُ ثُمَّ قَالَ ‏ ‏لِيُصَلِّ أَحَدُكُمْ نَشَاطَهُ فَإِذَا كَسِلَ ‏ ‏أَوْ ‏ ‏فَتَرَ ‏ ‏فَلْيَقْعُدْ ‏","","",""],[11549,11549,"","আমরা আপনাদের টাকা ভুলতে গিয়ে সমবেদনা জানাই।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِيٌّ لِرَجُلٍ فِي الْمَسْجِدِ ‏ ‏فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى قَامَ الْقَوْمُ ‏","","",""],[11550,11550,"","আমরা কথা বলেছিলাম, টাকা ভুলে আমাকে জিততে হবে। সে তোমার মুখ দিয়ে কি বলে তলোয়ারে এটা ব্যবহার করতে হবে, তা ভুলে গেছে। আর ঈশ্বরের কাছে আমাকে ব্যর্থ করতে বলেছে, আমি কিছু করতে পারিনি কেন?","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَخَذَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِيَدِي فَانْطَلَقَ بِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَنَسًا ‏ ‏غُلَامٌ ‏ ‏كَيِّسٌ ‏ ‏فَلْيَخْدُمْكَ قَالَ فَخَدَمْتُهُ فِي السَّفَرِ وَالْحَضَرِ ‏ ‏وَاللَّهِ مَا قَالَ لِي لِشَيْءٍ صَنَعْتُهُ لِمَ صَنَعْتَ هَذَا هَكَذَا وَلَا لِشَيْءٍ لَمْ أَصْنَعْهُ لِمَ لَمْ تَصْنَعْ هَذَا هَكَذَا ‏","","",""],[11551,11551,"","তিনি একটা আংটি দিয়েছিলেন যাতে আমরা হয়তো সীলকে সীল দিতে পারি আর সেটা নিয়ে ক্লান্ত হয়ে পড়তে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏اصْطَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا فَقَالَ إِنَّا ‏ ‏قَدْ اصْطَنَعْنَا خَاتَمًا وَنَقَشْنَا فِيهِ نَقْشًا فَلَا يَنْقُشُ أَحَدٌ عَلَيْهِ ‏","","",""],[11552,11552,"","আমরা যারা এই কথা বলেছিল তাদের সাথে যৌন সম্পর্ক স্থাপন করা সম্পর্কে কথা বলেছি, তারা বলেছিল যে এটা ছিল এবং এটা ছিল, তখন ছিল ছিল বধির এবং তার কাছে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوجِزُ الصَّلَاةَ وَيُكْمِلُهَا ‏","","",""],[11553,11553,"","আমরা বাবার সাথে তোমার ভালোবাসা ভুলে গিয়ে আমাদের সাথে সুখে থেকে কথা বলেছিলাম, সে কখনো বড় সময়ও দিত না আর তারপর তারা এই লক্ষণের কথা ভাবত।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَفْتَتِحُونَ الْقِرَاءَةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[11554,11554,"","আমরা কথা বলেছি যারা ঈশ্বরের দোহাই দিয়ে যায় তাদের যৌন সম্পর্ক করার কথা এবং তাদের তা করতে হবে। আমার ভালোর জন্য আমার বাবা আমার ছেলের অনুগ্রহের প্রশংসা করেছেন। আর ঈশ্বরের প্রাসাদে গিয়ে আত্মসমর্পণ করা তার পছন্দগুলোকে ধ্বংস করে দিয়েছে । সে যে কারনে বলেছিল, আমার বাবা বলেছিলেন, \"ঈশ্বর, আমি পাইলটকে মেরে ফেলব।\" একজন প্রতিবেশী বললো, তুমি এক গ্রীষ্মের মধ্যে বেঁচে আছো এবং তারপর একটা একটা করে। ( গীতসংহিতা ৩৬: ৯) ঈশ্বরের সামনে এক গ্রীষ্মের ছুটির দিনে আপনি এক আলো ও আলো ও আপনার জন্য প্রার্থনা করেছিলেন । তার শান্তি আছে আর সে একটা ভাল রাত পেয়েছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমি তাকে হারাব আর সে তাকে হারাব, এমনকি তার মা যদি বিয়ে করেও সে বিয়ে করে, সে ছিলো। যদি সে বলে যে তাকে ফিরিয়ে আনতে হবে, তাহলে সে ফিরে আসবে। সে শপথ নিয়ে আসবে এবং আমি মনে করি এটা হয়ত উল্লেখ করা হবে। সসেজ তাকে ভালো বোধ করতে বলে এবং ঈশ্বরের প্রতি ভক্তি ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَا ‏ ‏خَيْبَرَ ‏ ‏فَصَلَّيْنَا عِنْدَهَا صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏بِغَلَسٍ ‏ ‏فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَكِبَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَأَنَا ‏ ‏رَدِيفُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فَأَجْرَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏زُقَاقِ ‏ ‏خَيْبَرَ ‏ ‏وَإِنَّ رُكْبَتَيَّ لَتَمَسُّ فَخِذَيْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَانْحَسَرَ ‏ ‏الْإِزَارُ ‏ ‏عَنْ فَخِذَيْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنِّي لَأَرَى بَيَاضَ فَخِذَيْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا ‏ ‏بِسَاحَةِ ‏ ‏قَوْمٍ ‏ ‏فَسَاءَ ‏ ‏صَبَاحُ الْمُنْذَرِينَ قَالَهَا ثَلَاثَ مِرَارٍ قَالَ وَقَدْ خَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ فَقَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏وَقَالَ بَعْضُ أَصْحَابِنَا ‏ ‏الْخُمُسُ ‏ ‏قَالَ فَأَصَبْنَاهَا ‏ ‏عَنْوَةً ‏ ‏فَجُمِعَ ‏ ‏السَّبْيُ ‏ ‏قَالَ فَجَاءَ ‏ ‏دِحْيَةُ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ أَعْطِنِي جَارِيَةً مِنْ ‏ ‏السَّبْيِ ‏ ‏قَالَ اذْهَبْ فَخُذْ جَارِيَةً قَالَ فَأَخَذَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَعْطَيْتَ ‏ ‏دِحْيَةَ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏سَيِّدَةَ ‏ ‏قُرَيْظَةَ ‏ ‏وَالنَّضِيرِ ‏ ‏وَاللَّهِ مَا تَصْلُحُ إِلَّا لَكَ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْعُوهُ بِهَا فَجَاءَ بِهَا فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ خُذْ جَارِيَةً مِنْ ‏ ‏السَّبْيِ ‏ ‏غَيْرَهَا ثُمَّ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَهَا وَتَزَوَّجَهَا فَقَالَ لَهُ ‏ ‏ثَابِتٌ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏مَا ‏ ‏أَصْدَقَهَا ‏ ‏قَالَ نَفْسَهَا أَعْتَقَهَا وَتَزَوَّجَهَا حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏فَأَهْدَتْهَا لَهُ مِنْ اللَّيْلِ وَأَصْبَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَرُوسًا فَقَالَ مَنْ كَانَ عِنْدَهُ شَيْءٌ فَلْيَجِئْ بِهِ وَبَسَطَ نِطَعًا فَجَعَلَ الرَّجُلُ يَجِيءُ ‏ ‏بِالْأَقِطِ ‏ ‏وَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ ‏ ‏قَالَ وَأَحْسِبُهُ قَدْ ذَكَرَ ‏ ‏السَّوِيقَ ‏ ‏قَالَ ‏ ‏فَحَاسُوا ‏ ‏حَيْسًا ‏ ‏وَكَانَتْ وَلِيمَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11555,11555,"","আমরা তাদের কথা বলেছি যারা ঈশ্বরকে তার বাবা-মা'কে পাঠানোর চেষ্টা করছিল, সে তার মৃত্যুর আগ পর্যন্ত নিখোঁজ ছিল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏دِرْعُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرْهُونَةً مَا وَجَدَ مَا يَفْتَكُّهَا حَتَّى مَاتَ ‏","","",""],[11556,11556,"","আমরা কিছু টাকা নিয়ে কথা বলেছি... ...আমরা একটা ছেলে বেছে নিয়েছি... ...যে তার টাকা ভুলে গেছে, শহরের নদীগুলো অক্সিজেনের কথা দিয়েছে আমার প্রভু, আর অনুগ্রহে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَوْثَرُ نَهَرٌ فِي الْجَنَّةِ وَعَدَنِيهِ رَبِّي عَزَّ وَجَلَّ ‏","","",""],[11557,11557,"","ঈশ্বর আমাকে বলেছিলেন যে, তোমার মা যুদ্ধ করবে না, তারা লোকেদের বেছে নিতে পারবে না ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ تَعَالَى قَالَ لِي ‏ ‏إِنَّ أُمَّتَكَ لَا يَزَالُونَ يَتَسَاءَلُونَ فِيمَا بَيْنَهُمْ حَتَّى يَقُولُوا هَذَا اللَّهُ خَلَقَ النَّاسَ فَمَنْ خَلَقَ اللَّهَ ‏","","",""],[11558,11558,"","আমরা একটা কলম দিয়ে ভাড়া করা লোকের কথা বলেছিলাম... ...আমি শুনেছি তোমার টাকা বোকামির কাজ, তাকে একটা বোকা মোড় দেওয়া হয়েছে, অথবা তারা বলেছে তাকে খুন করতে হবে। আমি নিচে নামছি। আমি ঈশ্বরের অনুগ্রহের উপর যদি আমি ঈশ্বরের দয়া পড়ি এবং আমি ঈশ্বরের নামে তা পাঠ করা হয়েছে. আমার মা তোমাকে অনেক ধন্যবাদ যে আমার মা মৃত্যুদণ্ড দিতে চাইবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أَغْفَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِغْفَاءَةً فَرَفَعَ رَأْسَهُ مُتَبَسِّمًا ‏ ‏إِمَّا قَالَ لَهُمْ وَإِمَّا قَالُوا لَهُ ‏ ‏لِمَ ضَحِكْتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ أُنْزِلَتْ عَلَيَّ آنِفًا سُورَةٌ فَقَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ‏ ‏حَتَّى خَتَمَهَا قَالَ هَلْ تَدْرُونَ مَا الْكَوْثَرُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هُوَ نَهْرٌ أَعْطَانِيهِ رَبِّي عَزَّ وَجَلَّ فِي الْجَنَّةِ عَلَيْهِ خَيْرٌ كَثِيرٌ يَرِدُ عَلَيْهِ أُمَّتِي يَوْمَ الْقِيَامَةِ آنِيَتُهُ عَدَدُ الْكَوَاكِبِ يُخْتَلَجُ الْعَبْدُ مِنْهُمْ فَأَقُولُ يَا رَبِّ إِنَّهُ مِنْ أُمَّتِي فَيُقَالُ لِي إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[11559,11559,"","আমরা কয়েকদিন আগে কথা বলেছি, আমরা তার কাজের শ্রেণী থেকে টাকা ভুলে যাওয়ার কথা বলেছিলাম, সে সেদিনই হাল ছেড়ে দেবে, যখন সে প্রার্থনা ছেড়ে দেবে আর মানুষ আমাদের চুমু খাবে। ফিরে আসার দুঃখ, আর কখনো বাতিল হবে না, আমি তোমাকে বলেছিলাম, প্রভু, অথবা সে যদি আপনাকে এই পালানোর কথা বলে থাকে, তাহলে সে অনেক কিছু বলবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَقَدْ انْصَرَفَ مِنْ الصَّلَاةِ فَأَقْبَلَ إِلَيْنَا فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنِّي إِمَامُكُمْ فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ وَلَا بِالْقِيَامِ وَلَا بِالْقُعُودِ وَلَا ‏ ‏بِالِانْصِرَافِ فَإِنِّي أَرَاكُمْ مِنْ أَمَامِي وَمِنْ خَلْفِي وَايْمُ الَّذِي نَفْسِي بِيَدِهِ لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا قَالُوا يَا رَسُولَ اللَّهِ وَمَا رَأَيْتَ قَالَ رَأَيْتُ الْجَنَّةَ وَالنَّارَ ‏","","",""],[11560,11560,"","আমরা কিছু সময় দ্বারা বাপ্তাইজিত হয়েছি, বাবার ছেলের মাধ্যমে। সে ঈশ্বরের কাছে প্রার্থনা করতে বলেছে, প্রার্থনা করতে, প্রার্থনা করতে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عَمْرٍو يَعْنِي ابْنَ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَيَّ صَلَاةً وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرَ صَلَوَاتٍ وَحَطَّ عَنْهُ عَشْرَ خَطِيئَاتٍ ‏","","",""],[11561,11561,"","আমরা তোমাকে মারার ব্যাপারে কথা বলেছিলাম, আমি একজন রোমান নাগরিক, যখন আমরা বিকেলে প্রতিবেশীকে প্রার্থনা করলাম, তখন আমরা কয়েক বার প্রার্থনা করলাম। যখন আমরা প্রার্থনা করলাম তখন আমরা প্রার্থনা করলাম, যখন আমি ঈশ্বর সম্বন্ধে শুনেছি। ঈশ্বরের কাছে প্রার্থনা কর এবং বলবে যে ঈশ্বরের দয়া যেন তাঁর উপরে থাকে এবং তাঁর শান্তি তোমার উপর আসবে। যদি সে আমার শহরে থাকতো অথবা আমি তাকে গুলি করার সিদ্ধান্ত নিলাম, সে শয়তানকে গুলি করার সিদ্ধান্ত নিল, সে কখনো হত না। মনে রাখবে ওকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏حِينَ صَلَّيْنَا الظُّهْرَ فَدَعَا ‏ ‏الْجَارِيَةَ ‏ ‏بِوَضُوءٍ ‏ ‏فَقُلْنَا لَهُ أَيُّ صَلَاةٍ تُصَلِّي قَالَ الْعَصْرَ قَالَ قُلْنَا إِنَّمَا صَلَّيْنَا الظُّهْرَ الْآنَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تِلْكَ صَلَاةُ الْمُنَافِقِ يَتْرُكُ الصَّلَاةَ حَتَّى إِذَا كَانَتْ فِي قَرْنَيْ الشَّيْطَانِ ‏ ‏أَوْ بَيْنَ قَرْنَيْ الشَّيْطَانِ ‏ ‏صَلَّى لَا يَذْكُرُ اللَّهَ فِيهَا إِلَّا قَلِيلًا ‏","","",""],[11562,11562,"","আমরা কথা বলছিলাম সে কি বলছে সে ছেলে হবে না, ঈশ্বর তাকে তার পাপ নিতে বলেন এবং আপনি একটি সময় স্ট্যাম্প করার পরিকল্পনা করছেন ওকে নিয়ে যাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَتَبْسُطُ لَهُ نِطْعًا فَيَقِيلُ عَلَيْهِ فَتَأْخُذُ مِنْ عَرَقِهِ فَتَجْعَلُهُ فِي طِيبِهَا ‏ ‏وَتَبْسُطُ لَهُ ‏ ‏الْخُمْرَةَ ‏ ‏فَيُصَلِّي عَلَيْهَا ‏","","",""],[11563,11563,"","আমরা তোমার টাকা নিয়ে কথা বলেছি, এটা দিয়ে যাওয়ার কথা। আর উন্নতি করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ يَشْفَعَ الْأَذَانَ ‏ ‏وَيُوتِرَ ‏ ‏الْإِقَامَةَ ‏","","",""],[11564,11564,"","আমরা সেই দরজার উপর দিয়ে যাওয়ার কথা বলেছিলাম, আমার বাবার সাথে কথা বলেছিলাম আর তারপর সে মুখ বন্ধ করে দিল. সে যা ছেড়ে চলে যায়, তা থেকে ঈশ্বরকে রক্ষা করার পর সে তার গর্তে ফিরে যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ بِهِنَّ حَلَاوَةَ الْإِيمَانِ ‏ ‏أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَأَنْ يُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ مِنْهُ كَمَا يَكْرَهُ أَنْ يُوقَدَ لَهُ نَارٌ فَيُقْذَفَ فِيهَا ‏","","",""],[11565,11565,"","আমরা কথা বলেছিলাম, কিভাবে আমার বাবা আরো ভালো হওয়ার চেষ্টা করছিল, সে কখনোই পাগলের মত পাগলের মত তাকে ছেড়ে চলে যেতে দেয় না, আর বল থেকে তাকে আর বল দিয়ে দেখতে হয় না.","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَخْرُجَ مِنْهَا وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ غَيْرَ الشَّهِيدِ يُحِبُّ أَنْ يَخْرُجَ فَيُقْتَلَ لِمَا يَرَى مِنْ الْكَرَامَةِ أَوْ مَعْنَاهُ ‏","","",""],[11566,11566,"","আমরা তোমার টাকা ভুলের কথা বলেছিলাম তাকে মারতে না বলা পর্যন্ত সে আমার মাকে ছেড়ে দিবে না, সে কখনোই তোমার কাছে আসবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بُعِثَ نَبِيٌّ إِلَّا أَنْذَرَ أُمَّتَهُ الْأَعْوَرَ الْكَذَّابَ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ ‏","","",""],[11567,11567,"","হঠাৎ করে লোকেরা তার প্রার্থনা শুনে প্রার্থনা করেছিল, তিনি ভয় পেয়ে ভিতরে গিয়েছিলেন । আপনি প্রার্থনা করেছিলেন এবং আপনার প্রার্থনার পরিধি বাড়িয়ে তোলার জন্য আমরা চাই যেন তিনি জানতেন যে, আপনি কোথায় যেতে পারেন এবং কখন তা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي ذَاتَ لَيْلَةٍ فِي حُجْرَتِهِ فَجَاءَ أُنَاسٌ فَصَلَّوْا بِصَلَاتِهِ فَخَفَّفَ فَدَخَلَ الْبَيْتَ ثُمَّ خَرَجَ فَعَادَ مِرَارًا كُلَّ ذَلِكَ ‏ ‏يُصَلِّي فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ صَلَّيْتَ وَنَحْنُ نُحِبُّ أَنْ تَمُدَّ فِي صَلَاتِكَ قَالَ قَدْ ‏ ‏عَلِمْتُ بِمَكَانِكُمْ وَعَمْدًا فَعَلْتُ ذَلِكَ ‏","","",""],[11568,11568,"","আমরা আমার বাবার ছেলেকে বলছি যারা ঈশ্বরের শান্তিয় এসেছে আর মৃত্যধরা উদ্ধার করতে হবে। তারা প্রান্তরে খেলা করে বলে যে আপনি ভালোর জন্য ব্যবহার করতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَلَهُمْ يَوْمَانِ يَلْعَبُونَ فِيهِمَا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَدْ أَبْدَلَكُمْ بِهِمَا خَيْرًا مِنْهُمَا يَوْمَ الْفِطْرِ وَيَوْمَ ‏ ‏النَّحْرِ ‏","","",""],[11569,11569,"","আমরা বাবার ছেলেকে বলেছিলাম ঘোড়ার কথা। যারা বলে, নবী আল্লাহ এ ব্যাপারে একটা স্বপ্ন দেখেন। ঈশ্বর যেন তোমাকে কবরে ফেলে যেতে না পারেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَائِطًا مِنْ ‏ ‏حِيطَانِ ‏ ‏بَنِي النَّجَّارِ ‏ ‏فَسَمِعَ صَوْتًا مِنْ قَبْرٍ فَسَأَلَ عَنْهُ مَتَى دُفِنَ هَذَا فَقَالُوا يَا رَسُولَ اللَّهِ دُفِنَ هَذَا فِي الْجَاهِلِيَّةِ فَأَعْجَبَهُ ذَلِكَ وَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[11570,11570,"","আমরা বাবার ছেলেকে একটি ঘোড়ার কথা বলেছি, যারা বলেছে, ঈশ্বর এটা দেয়ালের মধ্যে দিয়ে করেছেন। আমি ব্যস্ত নদী, ভয় পেয়ে আমার হাত চলে যাবে। আমার কাছে ভালো লাগে। আমি আমার বাবার ছেলেকে একটা ঘোড়া দিয়ে বলছি, তুমি ঈশ্বর.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا بِنَهْرٍ حَافَتَاهُ خِيَامُ اللُّؤْلُؤِ فَضَرَبْتُ بِيَدِي إِلَى مَا يَجْرِي فِيهِ الْمَاءُ فَإِذَا ‏ ‏مِسْكٌ ‏ ‏أَذْفَرُ ‏ ‏قُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَهُ اللَّهُ ‏","","",""],[11571,11571,"","আমরা বাবার ছেলেকে বলেছিলাম, সে কখনো ঈশ্বরের কাছে ফিরে আসবে না। তুমি মনে করো আমরা শহরের কাছ থেকে হারিয়ে গেছি। ঈশ্বর আপনাকে একজন শপথী দাস বলে ডাকা হয়েছে। যে শহরে তারা নিজেদের শহরে আছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَدَنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِالْمَدِينَةِ ‏ ‏لَقَوْمًا مَا سِرْتُمْ مَسِيرًا وَلَا قَطَعْتُمْ وَادِيًا إِلَّا كَانُوا مَعَكُمْ فِيهِ قَالُوا يَا رَسُولَ اللَّهِ وَهُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ وَهُمْ ‏ ‏بِالْمَدِينَةِ ‏ ‏حَبَسَهُمْ الْعُذْرُ ‏","","",""],[11572,11572,"","আমরা বাবার ছেলেকে বলেছিলাম ঘোড়ার জন্য এটা ঈশ্বরের অনুগ্রহ। দুঃখটা কখনোই আমার ঊর্ধ্বতনদের দ্বারা লড়াই করা হয়নি। সত্যিই মোটা থেকে কিছুই দিতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ نَاقَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسَمَّى ‏ ‏الْعَضْبَاءَ ‏ ‏وَكَانَتْ لَا تُسْبَقُ فَجَاءَ أَعْرَابِيٌّ عَلَى ‏ ‏قَعُودٍ ‏ ‏فَسَبَقَهَا فَشَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَلَمَّا رَأَى مَا فِي وُجُوهِهِمْ قَالُوا يَا رَسُولَ اللَّهِ سُبِقَتْ ‏ ‏الْعَضْبَاءُ ‏ ‏فَقَالَ ‏ ‏إِنَّ حَقًّا عَلَى اللَّهِ أَنْ لَا يَرْفَعَ شَيْئًا مِنْ الدُّنْيَا إِلَّا وَضَعَهُ ‏","","",""],[11573,11573,"","আমরা বাবার ছেলের সাথে কথা বলেছি, প্রভুর কাছে প্রার্থনা করা লোকের স্বপ্নের কথা যারা বলে প্রভুর কাছে প্রার্থনা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ وَتَرَاصُّوا فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏","","",""],[11574,11574,"","আমরা বাবার ছেলের সাথে কথা বলেছি, তিনি বলেছিলেন তিনি ঈশ্বরের দয়া ও শান্তি চান। আমরা তাকে রাতের বেলা প্রার্থনা করতে দেখিনি, যখন আমরা তাকে দেখতে যাচ্ছি। সে কিছু মনে করে না বলে, আর সে ভাবলো আমরা বলি এটা ঘটে না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَقَالَ ‏ ‏مَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ مِنْ اللَّيْلِ مُصَلِّيًا إِلَّا رَأَيْنَاهُ وَمَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ نَائِمًا إِلَّا رَأَيْنَاهُ وَكَانَ يَصُومُ مِنْ الشَّهْرِ حَتَّى نَقُولَ لَا يُفْطِرُ مِنْهُ شَيْئًا وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ مِنْهُ شَيْئًا ‏","","",""],[11575,11575,"","আমরা বাবার ছেলেকে বলেছিলাম যে, আমরা লর্ডের কাছ থেকে এসেছি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আমার অবিবাহিত সংগ্রামের জেগে তিনি আত্মসমর্পণ করেছেন, প্রভু, ( গীতসংহিতা ৩৪: ৬) ঈশ্বর যখন তাঁর প্রার্থনা থেকে পালিয়ে এসেছিলেন, তখন তিনি বলেছিলেন যে, তিনি সাহায্য চান, তা তিনি চান । আমি যাদের বলতে চাই, তাদের সঙ্গে সঙ্গে লোকেরা সিঁড়ির নিচে বসে খুশি হয় । চুপ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَيَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَتَى قِيَامُ السَّاعَةِ وَأُقِيمَتْ الصَّلَاةُ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ قَالَ أَنَا يَا رَسُولَ اللَّهِ قَالَ وَمَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ عَمَلٍ لَا صَلَاةٍ وَلَا صِيَامٍ إِلَّا أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَمَا رَأَيْتُ الْمُسْلِمِينَ فَرِحُوا بَعْدَ الْإِسْلَامِ بِشَيْءٍ مَا فَرِحُوا بِهِ ‏","","",""],[11576,11576,"","আমরা বাবার ছেলের সাথে কথা বলেছি যে মানুষ সম্পর্কে তার প্রার্থনা করা হয়েছে। কিন্তু তার মেয়েরা কিছু বলতে চায় হঠাৎ করে আমি কিছু বলতে চাই যে আমি বাইরে যাচ্ছি। প্রার্থনা করছি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَقَدْ كَانَ بَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ نِسَائِهِ شَيْءٌ ‏ ‏فَجَعَلَ يَرُدُّ بَعْضَهُنَّ عَنْ بَعْضٍ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ احْثُ يَا رَسُولَ اللَّهِ فِي أَفْوَاهِهِنَّ التُّرَابَ وَاخْرُجْ إِلَى الصَّلَاةِ ‏","","",""],[11577,11577,"","আমরা বাবার ছেলেকে একটা ঘোড়ার কথা বলেছি, যারা বলেছে যে খোদা তাদের পতাকা তুলে তার কাছে সমর্পণ করেছে এবং তার কাছে আত্মসমর্পণ করেছে, মৃত্যু হচ্ছে তার নিজেরই অপচয়, কিন্তু এটা বলছে ঈশ্বর আমার পাশে আরেক পথ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَتَمَنَّيَنَّ أَحَدُكُمْ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ وَلَكِنْ لِيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[11578,11578,"","আমরা আমার বাবার ছেলের কথা বলেছি মানুষের জন্য ঘোড়ার বদলে ঘোড়া বানানো একজন পেইন্টার যে এই ভুলটা করতে পারে। আত্মসমর্পণ করতে হতো না ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يُكْثِرُ الصَّوْمَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا مَاتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَا يُفْطِرُ إِلَّا فِي سَفَرٍ أَوْ مَرَضٍ ‏","","",""],[11579,11579,"","আমরা বাবার ছেলেকে কথা বলেছি... ...তাদের জন্য ঘোড়ার পিঠে চড়ে... ...যে বলেছিল, সে এটা করেছে আর তাকে জিজ্ঞেস করেছে যে সে ঠিক আছে কিনা। দুই বছর আগে, আমি যদি আমার সামনে এগিয়ে যেতে পারি, তাহলে আমি ১০ জনেই যাব। বাবা, আমি ফোন করব না, আমার বাবা সাধারণ মানুষ রক্ষা করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ مُقِيمًا ‏ ‏اعْتَكَفَ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ وَإِذَا سَافَرَ ‏ ‏اعْتَكَفَ ‏ ‏مِنْ الْعَامِ الْمُقْبِلِ عِشْرِينَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَمْ أَسْمَعْ هَذَا الْحَدِيثَ إِلَّا مِنْ ‏ ‏ابْنِ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏","","",""],[11580,11580,"","আমরা বাবার ছেলেকে বলেছিলাম একটা ঘোড়া সম্পর্কে যে আমাকে বলেছে যে এটা উদ্ধার করতে হবে। আর তারপর তার মা যখন তাকে হত্যা করতে দেখেন তখন তিনি ভয় পান যে তাকে হত্যা করা হবে, ঈশ্বর, আল্লাহ, তার ছেলের সঙ্গে এই কাজটি করলে তারা বলেছিল যে, ঈশ্বর যদি এই আগুন থেকে তাকে রক্ষা করতে পারতেন, তাহলে ঈশ্বর তাকে আগুনে পুড়িয়ে ফেলতে পারতেন না।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏نَفَرٍ ‏ ‏مِنْ أَصْحَابِهِ وَصَبِيٌّ فِي الطَّرِيقِ فَلَمَّا رَأَتْ أُمُّهُ الْقَوْمَ خَشِيَتْ عَلَى وَلَدِهَا أَنْ ‏ ‏يُوطَأَ ‏ ‏فَأَقْبَلَتْ ‏ ‏تَسْعَى وَتَقُولُ ابْنِي ابْنِي وَسَعَتْ فَأَخَذَتْهُ فَقَالَ الْقَوْمُ يَا رَسُولَ اللَّهِ مَا كَانَتْ هَذِهِ لِتُلْقِيَ ابْنَهَا فِي النَّارِ قَالَ فَخَفَّضَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏وَلَاءُ ‏ ‏اللَّهِ عَزَّ وَجَلَّ لَا يُلْقِي حَبِيبَهُ فِي النَّارِ ‏","","",""],[11581,11581,"","আমরা বাবার ছেলের সাথে কথা বলেছি, তিনি বলেছিলেন যে তিনি মানুষকে জিজ্ঞাসা করতে হবে তিনি উপস্থিত মানুষ জিজ্ঞাসা. তিনি বলেন তিনি ভিড় ছিল, স্যার, কিন্তু তিনি আগুন পেয়েছিলাম এবং তিনি রোগ খুঁজে পেয়েছেন. তিনি পুনরায় জীবিত হবেন, আর তিনি হয়তো তার হাত বাড়িয়ে আকাশে দেখবেন যে তিনি জয়ী হবেন । যে তাকে অনুসরণ করছিল, সে ছিল তার পিছু নিয়েছে। সে ঈশ্বরের ইচ্ছার উপর বিষ প্রয়োগ করেছিল এবং এক ছেলের গতি দ্বারা তাকে উদ্ধার করে যে সন্তান জন্ম নেয়, সে ছিল সেই ছেলে। যে ই বা সেই একমাত্র ব্যক্তি যে কিনা এই বিষয়ে কথা বলেছিল যে সে ছিল সেই লোক যে আমিই এক ব্যক্তি যিনি ছিলেন সেই ব্যক্তি ছিল সেই ব্যক্তি যে কিনা ছিল, সে শহরের শহরগুলোর সাথে সম্পর্ক ভেঙে ফেলেছিল।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏هَلْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ فَقَالَ قِيلَ لَهُ يَوْمَ الْجُمُعَةِ يَا رَسُولَ اللَّهِ ‏ ‏قَحَطَ ‏ ‏الْمَطَرُ وَأَجْدَبَتْ الْأَرْضُ وَهَلَكَ الْمَالُ قَالَ ‏ ‏فَرَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ فَاسْتَسْقَى وَلَقَدْ رَفَعَ يَدَيْهِ فَاسْتَسْقَى وَلَقَدْ رَفَعَ يَدَيْهِ وَمَا نَرَى فِي السَّمَاءِ سَحَابَةً فَلَمَّا قَضَيْنَا الصَّلَاةَ حَتَّى إِنَّ قَرِيبَ الدَّارِ الشَّابَّ لَيُهِمُّهُ الرُّجُوعَ إِلَى أَهْلِهِ قَالَ فَلَمَّا كَانَتْ الْجُمُعَةُ الَّتِي تَلِيهَا قَالُوا يَا رَسُولَ اللَّهِ تَهَدَّمَتْ الْبُيُوتُ وَاحْتُبِسَتْ ‏ ‏الرُّكْبَانُ ‏ ‏فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سُرْعَةِ مَلَالَةِ ابْنِ ‏ ‏آدَمَ ‏ ‏وَقَالَ اللَّهُمَّ ‏ ‏حَوَالَيْنَا ‏ ‏وَلَا عَلَيْنَا ‏ ‏فَتَكَشَّطَتْ ‏ ‏عَنْ ‏ ‏الْمَدِينَةِ ‏","","",""],[11582,11582,"","আমরা বাবার ছেলের সাথে কথা বলেছি... ...যারা সে যে ভবিষ্যদ্বাণীটা শুনেছিল... ...আর তার হাত তার নিজের হাত আছে, বাবা, একজন চমৎকার দাস, একজন চমৎকার দাস, একজন চমৎকার দাস, একজন মহান দাস আমি তাদের কাছ থেকে কেন বলব, কিন্তু তারা উত্তর দিতে পারে না","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَمِعَ الْمُسْلِمُونَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُنَادِي عَلَى ‏ ‏قَلِيبِ بَدْرٍ ‏ ‏يَا ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏يَا ‏ ‏عُتْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏شَيْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏أُمَيَّةُ بْنَ خَلَفٍ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا فَإِنِّي وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا قَالُوا يَا رَسُولَ اللَّهِ تُنَادِي قَوْمًا قَدْ ‏ ‏جَيَّفُوا ‏ ‏قَالَ ‏ ‏مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ وَلَكِنَّهُمْ لَا يَسْتَطِيعُونَ أَنْ يُجِيبُوا ‏","","",""],[11583,11583,"","আমরা বাবার ছেলেকে একটা ঘোড়ার কথা বলেছি যারা ভুলে গেছে যে ঈশ্বর এটা ভুলে গেছে আর আমাকে এটা করতে বলেছেন, আমি তোমাকে বিচার করিনি, ঈশ্বর তোমাকে দোষ দিয়েছেন, আমাকে বলেছে, প্রভু। তারা বলেছে, আমাকে এটা বলতে, তারা বলেছিল আমরা এসেছি আর তারা বিশ্বাস করে আপনি স্বাধীন আর ভুল, আপনি আমাদের সাথে কথা বলছেন এবং তার প্রার্থনা দেখে...","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَمْ آتِكُمْ ضُلَّالًا فَهَدَاكُمْ اللَّهُ عَزَّ وَجَلَّ بِي أَلَمْ آتِكُمْ مُتَفَرِّقِينَ فَجَمَعَكُمْ اللَّهُ بِي أَلَمْ آتِكُمْ أَعْدَاءً فَأَلَّفَ اللَّهُ بَيْنَ قُلُوبِكُمْ بِي قَالُوا بَلَى ‏ ‏يَا رَسُولَ اللَّهِ قَالَ أَفَلَا تَقُولُونَ جِئْتَنَا خَائِفًا فَآمَنَّاكَ وَطَرِيدًا فَآوَيْنَاكَ وَمَخْذُولًا فَنَصَرْنَاكَ فَقَالُوا بَلْ لِلَّهِ تَبَارَكَ وَتَعَالَى ‏ ‏الْمَنُّ ‏ ‏بِهِ عَلَيْنَا وَلِرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11584,11584,"","আমরা বাবার ছেলেকে বলেছিলাম যে সে মানুষের জন্য ঘোড়ার মতো ঘোড়া নিয়ে যাবে, সে বলল সে যখন ঈশ্বরের সালাদ নিয়ে বের হয়, সে বাইরে বের হয়ে যায়, মানুষ তাকে আমার বাবার মত দেখে, যেমন ঈশ্বর তাকে দেখেছেন, তুমি তাকে মেরে ফেলেছ। যখন সে চায় তুমি ঈশ্বর আর ঈশ্বর বলবে না, তখন আমার কাছে স্যামম তোমাকে খুন করতে দেবে, কিন্তু মেঘের মত আমরা তোমার সাথে আছি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا سَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏بَدْرٍ ‏ ‏خَرَجَ ‏ ‏فَاسْتَشَارَ النَّاسَ فَأَشَارَ عَلَيْهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ثُمَّ اسْتَشَارَهُمْ فَأَشَارَ عَلَيْهِ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَسَكَتَ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنَّمَا يُرِيدُكُمْ فَقَالُوا يَا رَسُولَ اللَّهِ وَاللَّهِ لَا نَكُونُ كَمَا قَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏لِمُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ { ‏اذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ ‏} ‏وَلَكِنْ وَاللَّهِ لَوْ ضَرَبْتَ أَكْبَادَ الْإِبِلِ حَتَّى تَبْلُغَ ‏ ‏بَرْكَ الْغِمَادِ ‏ ‏لَكُنَّا مَعَكَ ‏","","",""],[11585,11585,"","আমরা বাবার ছেলের সাথে কথা বলেছি... ...যে কিনা ঈশ্বরের পতাকার দিকে পতাকা রাখে। সে সকালে একটা দুই ম্যারোডি স্যুট দিয়ে একটা করে দেয়। এক, সে তাদের বলবে সে তার বাসায় ফিরে আসবে আর আমি তার সাথে থাকব, হোয়াইট ভিলেজ তার সাথে থাকবে না। যখন এটা তাদের কাছে আসে, তখন সে সফল হতে পারে যখন সে ছেলেটিকে দেখেছে। যে এটা করেছে আর তাকে ছেড়ে দিতে হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَعَوْتُ الْمُسْلِمِينَ إِلَى ‏ ‏وَلِيمَةِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَبِيحَةَ بَنَى ‏ ‏بِزَيْنَبَ بِنْتِ جَحْشٍ ‏ ‏فَأَشْبَعَ الْمُسْلِمِينَ خُبْزًا وَلَحْمًا قَالَ ثُمَّ رَجَعَ كَمَا كَانَ يَصْنَعُ فَأَتَى ‏ ‏حُجَرَ ‏ ‏نِسَائِهِ فَسَلَّمَ عَلَيْهِنَّ فَدَعَوْنَ لَهُ قَالَ ثُمَّ رَجَعَ إِلَى بَيْتِهِ وَأَنَا مَعَهُ فَلَمَّا انْتَهَى إِلَى الْبَيْتِ فَإِذَا رَجُلَانِ قَدْ جَرَى بَيْنَهُمَا الْحَدِيثُ فِي نَاحِيَةِ الْبَيْتِ فَلَمَّا بَصَرَ بِهِمَا وَلَّى رَاجِعًا فَلَمَّا رَأَى الرَّجُلَانِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ وَلَّى عَنْ بَيْتِهِ قَامَا مُسْرِعَيْنِ ‏ ‏فَلَا أَدْرِي أَنَا أَخْبَرْتُهُ أَوْ أُخْبِرَ بِهِ ‏ ‏ثُمَّ رَجَعَ إِلَى مَنْزِلِهِ ‏ ‏وَأَرْخَى السِّتْرَ بَيْنِي وَبَيْنَهُ وَأُنْزِلَتْ ‏ ‏آيَةُ الْحِجَابِ ‏","","",""],[11586,11586,"","আমরা বাবার ছেলেকে একটা ঘোড়ার কথা বলেছিলাম... ...সে বলল যে, সে আমাকে তার হাতে ছুড়ে মেরেছে। সে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল, সে তার মাথা তুলে ফেলবে। তার বুক ঈশ্বরের কাছে পাঠানো হয়েছে এবং তিনি ঈশ্বর, প্রভু, প্রভু, প্রভু, প্রভু, বলবে আমাদের স্বাধীনতা, আপনার কাছে মুক্ত থাকবে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَرْمِي بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ رَأْسَهُ مِنْ خَلْفِهِ لِيَنْظُرَ إِلَى مَوَاقِعِ نَبْلِهِ قَالَ فَتَطَاوَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِصَدْرِهِ ‏ ‏يَقِي بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ يَا رَسُولَ اللَّهِ نَحْرِي دُونَ نَحْرِكَ ‏","","",""],[11587,11587,"","আমরা বাবার ছেলেকে বলেছিলাম, সে তার ছেলের জন্য ঘোড়া নিয়ে যাবে। যে কিনা নিজের জন্য ঈশ্বরের জন্য করতে পারত। আমার ছেলে ঈগল, প্রতিবেশী, তারপর আমি আমার ছেলের সাথে ঘুরে বেড়াই, তারপর আমি আমার ছেলের সাথে ঘুরে বেড়াবো, তারপর আমি আমার ছেলের সাথে। ♪ আর সব রোটরদের সাথে কাটাও ♪","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏دَارُ ‏ ‏بَنِي النَّجَّارِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي عَبْدِ الْأَشْهَلِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏ثُمَّ دَارُ ‏ ‏بَنِي سَاعِدَةَ ‏ ‏وَفِي كُلِّ دُورِ ‏ ‏الْأَنْصَارِ ‏ ‏خَيْرٌ ‏","","",""],[11588,11588,"","আমরা বাবার ছেলের সাথে কথা বলেছি... ...যারা বলেছে খোদা তার পতাকা তুলে দিয়েছেন আর আত্মসমর্পণ করেছেন. আমরা এটার প্রতি ভালোবাসা অনুভব করি, আর আমরা এটা ভালোবাসি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْدَمُ عَلَيْكُمْ أَقْوَامٌ هُمْ أَرَقُّ مِنْكُمْ قُلُوبًا قَالَ فَقَدِمَ ‏ ‏الْأَشْعَرِيُّونَ ‏ ‏فِيهِمْ ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏فَلَمَّا دَنَوْا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏كَانُوا ‏ ‏يَرْتَجِزُونَ ‏ ‏يَقُولُونَ ‏ ‏غَدًا نَلْقَى ‏ ‏الْأَحِبَّهْ ‏ ‏مُحَمَّدًا ‏ ‏وَحِزْبَهْ ‏","","",""],[11589,11589,"","আমরা আমার বাবার ছেলের সাথে একটা ঘোড়ার কথা বলেছি যেটা বলা উচিত ঈশ্বরের কাছে। তার কিছু মহিলা বলেছে যে সে একটা হারবে যে তার মায়ের সাথে তার অনুপ্রেরণার সম্পর্ক ছিল। তিনি শপথ করেছিলেন যে, আপনার মায়ের কাছে শপথ করে দুটো চিনি নিয়ে যান এবং পরে তারা বলে যে, সেই মৃতদেহের মধ্যে দু - বার কেটে ফেলা হয়েছে । আর টুকরো টুকরোটা এমনকি বার্তাবাহককে শেষ বুথে যেতে দিতে গিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عِنْدَ بَعْضِ نِسَائِهِ قَالَ أَظُنُّهَا ‏ ‏عَائِشَةَ ‏ ‏فَأَرْسَلَتْ ‏ ‏إِحْدَى ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ ‏ ‏مَعَ خَادِمٍ لَهَا ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا طَعَامٌ قَالَ فَضَرَبَتْ الْأُخْرَى بِيَدِ الْخَادِمِ فَكُسِرَتْ ‏ ‏الْقَصْعَةُ ‏ ‏بِنِصْفَيْنِ قَالَ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غَارَتْ أُمُّكُمْ قَالَ وَأَخَذَ الْكَسْرَتَيْنِ فَضَمَّ إِحْدَاهُمَا إِلَى الْأُخْرَى فَجَعَلَ فِيهَا الطَّعَامَ ثُمَّ قَالَ كُلُوا فَأَكَلُوا وَحَبَسَ الرَّسُولَ ‏ ‏وَالْقَصْعَةَ ‏ ‏حَتَّى فَرَغُوا فَدَفَعَ إِلَى الرَّسُولِ ‏ ‏قَصْعَةً ‏ ‏أُخْرَى وَتَرَكَ الْمَكْسُورَةَ مَكَانَهَا ‏","","",""],[11590,11590,"","আমরা বাবার ছেলেকে বলেছিলাম, তুমি আমার বাবার ছেলে, অন্ধকার আমার মা, মৃত্যুর প্রভু, যিনি বলেছিলেন তিনি আসলে আমার বাবা। সেই মহিলার শক্তি ছিল শেষ রাত, যে - যন্ত্রণাটা ছিল সেটা বলার জন্য, তারা তাকে ঘৃণা করত । ঈশ্বর তাকে যুদ্ধ করতে বলেছেন। কাল এটি শুনতে পাবেন আর যখনই আমি খুঁজে পাই যে এটা হারিয়ে যাবে, তখনই তা শোনা যাবে । একবার সে কিছু খেয়ে ফেলে আর তারপর সময় নষ্ট করে ফেলে। আমি বললাম, প্রভু, সে হয়ত আমাদের সাথে এমন করেছে যেন আমাদের কাছে এমন কিছু হয়েছে যা আমাদের ছেলে বলেছিল। আমি এটা করেছি, আমার বাবার ছেলের সাথে আমার বাবার ছেলের সাথে একটা ছাপ করেছি। বাবা তার জন্য প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন যে, তিনি মারা গিয়েছেন । সে বলেছিল সে প্রথম হবে স্যারেনের ছেলে, তোমার টাকা ভুলে যাওয়ার ভয়ে... ...আমার বাবা একজন তালাকপ্রাপ্ত মা আর বাবা ছিল স্বাভাবিক. আর বলো খোদা এটা করেছে, ঈশ্বর তোমার জন্য বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏اشْتَكَى ابْنٌ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏فَخَرَجَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏إِلَى الْمَسْجِدِ فَتُوُفِّيَ الْغُلَامُ فَهَيَّأَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏الْمَيِّتَ وَقَالَتْ لِأَهْلِهَا لَا يُخْبِرَنَّ أَحَدٌ مِنْكُمْ ‏ ‏أَبَا طَلْحَةَ ‏ ‏بِوَفَاةِ ابْنِهِ فَرَجَعَ إِلَى أَهْلِهِ وَمَعَهُ نَاسٌ مِنْ أَهْلِ الْمَسْجِدِ مِنْ أَصْحَابِهِ قَالَ مَا فَعَلَ الْغُلَامُ قَالَتْ خَيْرٌ مِمَّا كَانَ فَقَرَّبَتْ إِلَيْهِمْ عَشَاءَهُمْ فَتَعَشَّوْا وَخَرَجَ الْقَوْمُ وَقَامَتْ الْمَرْأَةُ إِلَى مَا تَقُومُ إِلَيْهِ الْمَرْأَةُ فَلَمَّا كَانَ آخِرُ اللَّيْلِ قَالَتْ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏أَلَمْ تَرَ إِلَى آلِ فُلَانٍ اسْتَعَارُوا ‏ ‏عَارِيَةً ‏ ‏فَتَمَتَّعُوا بِهَا فَلَمَّا طُلِبَتْ كَأَنَّهُمْ كَرِهُوا ذَاكَ قَالَ مَا أَنْصَفُوا قَالَتْ فَإِنَّ ابْنَكَ كَانَ ‏ ‏عَارِيَةً ‏ ‏مِنْ اللَّهِ تَبَارَكَ وَتَعَالَى وَإِنَّ اللَّهَ قَبَضَهُ ‏ ‏فَاسْتَرْجَعَ ‏ ‏وَحَمِدَ اللَّهَ فَلَمَّا أَصْبَحَ غَدَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَآهُ قَالَ ‏ ‏بَارَكَ اللَّهُ لَكُمَا فِي لَيْلَتِكُمَا فَحَمَلَتْ ‏ ‏بِعَبْدِ اللَّهِ ‏ ‏فَوَلَدَتْهُ لَيْلًا وَكَرِهَتْ أَنْ ‏ ‏تُحَنِّكَهُ ‏ ‏حَتَّى ‏ ‏يُحَنِّكَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمَلْتُهُ ‏ ‏غُدْوَةً ‏ ‏وَمَعِي تَمَرَاتُ عَجْوَةٍ ‏ ‏فَوَجَدْتُهُ يَهْنَأُ أَبَاعِرَ لَهُ ‏ ‏أَوْ يَسِمُهَا ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَدَتْ اللَّيْلَةَ فَكَرِهَتْ أَنْ ‏ ‏تُحَنِّكَهُ ‏ ‏حَتَّى ‏ ‏يُحَنِّكَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَمَعَكَ شَيْءٌ قُلْتُ تَمَرَاتُ عَجْوَةٍ فَأَخَذَ بَعْضَهُنَّ فَمَضَغَهُنَّ ثُمَّ جَمَعَ بُزَاقَهُ فَأَوْجَرَهُ إِيَّاهُ فَجَعَلَ ‏ ‏يَتَلَمَّظُ ‏ ‏فَقَالَ حُبُّ ‏ ‏الْأَنْصَارِ ‏ ‏التَّمْرَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ سَمِّهِ قَالَ هُوَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏بُنْدَارٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏بَعْضَ هَذَا الْحَدِيثِ قَالَ فَأَتَيْتُهُ وَعَلَيْهِ ‏ ‏بُرْدَةٌ ‏ ‏حَدَّثَنَا ‏ ‏بُنْدَارٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏فَأَتَيْتُهُ وَعَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏لَهُ وَهُوَ فِي ‏ ‏الْحَائِطِ ‏ ‏يَسِمُ الظَّهْرَ الَّذِي قَدِمَ عَلَيْهِ فَقَالَ رُوَيْدَكَ أَفْرُغُ لَكَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِىٍّ ‏ ‏فِي أَوَّلِ الْحَدِيثِ ‏ ‏إِنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏غَدَا ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بِتُّمَا عَرُوسَيْنِ قَالَ فَبَارَكَ اللَّهُ لَكُمَا فِي عُرْسِكُمَا وَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏كَيْفَ ذَاكَ الْغُلَامُ قَالَتْ هُوَ أَهْدَأُ مِمَّا كَانَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَهِيَ أُمُّ ‏ ‏أَنَسٍ ‏ ‏وَالْبَرَاءِ ‏ ‏فَوَلَدَتْ لَهُ وَلَدًا وَكَانَ يُحِبُّهُ فَذَكَرَ الْحَدِيثَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبِتُّمَا عَرُوسَيْنِ وَهُوَ إِلَى جَنْبِكُمَا فَقَالَ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ بَارَكَ اللَّهُ لَكُمَا فِي لَيْلَتِكُمَا ‏","","",""],[11591,11591,"","আমরা বাবার ছেলেকে বলেছিলাম, আমরা হাত করেছি আর আমাদের নেতাকে বলেছি, তিনি আমাদের সকল মসজিদের ডক করেছেন আর আমি আমার নিজের রক্ত খেয়েছিলাম. শুধু এটা ভেঙ্গে ফেলা আর তার আঙ্গুল বলে যে সে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏نُودِيَ بِالصَّلَاةِ فَقَامَ كُلُّ قَرِيبِ الدَّارِ مِنْ الْمَسْجِدِ وَبَقِيَ مَنْ كَانَ أَهْلُهُ نَائِيَ الدَّارِ ‏ ‏فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِخْضَبٍ ‏ ‏مِنْ حِجَارَةٍ فَصَغُرَ أَنْ يَبْسُطَ أَكُفَّهُ فِيهِ قَالَ فَضَمَّ أَصَابِعَهُ قَالَ فَتَوَضَّأَ بَقِيَّتُهُمْ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَسُئِلَ ‏ ‏أَنَسٌ ‏ ‏كَمْ كَانُوا قَالَ ‏ ‏ثَمَانِينَ أَوْ زِيَادَةً ‏","","",""],[11592,11592,"","আমরা বাবার ছেলেকে বলছি... ...যে মানুষ ঘোড়ায় চড়ে আমি জন্ম দিতে চাই, তোমার প্রেরিতের গৌরবের জন্য প্রার্থনা করে... ...তুমি আত্মসমর্পণ করবে আর তোমার উপাসনা করতে পারবে না। তাদের দেখে প্রভাবিত হচ্ছে, তারা আমাকে বলেছে প্রভু, আমি এটা করবো।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَرَادُوا أَنْ يَتَحَوَّلُوا مِنْ مَنَازِلِهِمْ فَيَسْكُنُوا قُرْبَ الْمَسْجِدِ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَرِهَ أَنْ ‏ ‏تُعْرَى ‏ ‏الْمَدِينَةُ ‏ ‏فَقَالَ يَا ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَلَا تَحْتَسِبُونَ آثَارَكُمْ إِلَى الْمَسْجِدِ قَالُوا بَلَى يَا رَسُولَ اللَّهِ فَأَقَامُوا ‏","","",""],[11593,11593,"","আমরা বাবার ছেলেকে কথা বলেছি এবং সে হয়তো হঠাৎ করেই সবচেয়ে ভালো মানুষটি পাবে বা সে অনেক দূরে চলে গেছে। ঈশ্বর তার প্রার্থনা করেছেন এবং তার আত্মসমর্পণ করেছেন। প্রার্থনা করার জন্য, আপনি যা বলেছেন অথবা আপনার কাছে ক্ষমতা ছেড়ে দিয়েছেন। তিনি বলেননি যে \"আমি হত্যা করতে চাই\" এবং তারা বলে যে আপনি প্রার্থনা করতে আসেন এবং না চান। আমি এটা করতে পারবো।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏وَسُهَيْلُ بْنُ يُوسُفَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَجَاءَ رَجُلٌ ‏ ‏يَسْعَى ‏ ‏فَانْتَهَى وَقَدْ ‏ ‏حَفَزَهُ ‏ ‏النَّفَسُ أَوْ انْبَهَرَ فَلَمَّا انْتَهَى إِلَى الصَّفِّ قَالَ الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَهُ قَالَ أَيُّكُمْ الْمُتَكَلِّمُ فَسَكَتَ الْقَوْمُ فَقَالَ أَيُّكُمْ الْمُتَكَلِّمُ فَإِنَّهُ قَالَ خَيْرًا ‏ ‏أَوْ لَمْ يَقُلْ بَأْسًا ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَنَا أَسْرَعْتُ الْمَشْيَ فَانْتَهَيْتُ إِلَى الصَّفِّ فَقُلْتُ الَّذِي قُلْتُ قَالَ لَقَدْ ‏ ‏رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا يَبْتَدِرُونَهَا أَيُّهُمْ يَرْفَعُهَا ثُمَّ قَالَ إِذَا جَاءَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلْيَمْشِ عَلَى ‏ ‏هِينَتِهِ ‏ ‏فَلْيُصَلِّ مَا أَدْرَكَ وَلْيَقْضِ مَا سُبِقَهُ ‏","","",""],[11594,11594,"","আমরা বাবার ছেলেকে বলেছি, তার জন্য ঈশ্বরের অনুগ্রহ আছে কয়েকজনের কথা। আমি স্বর্গে গিয়েছিলাম, বেনের আবেগ শুনেছি, তাই আমরা আকাশের দিকে তাকিয়ে আছি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ بَيْنَ يَدَيَّ ‏ ‏خَشْفَةً ‏ ‏فَإِذَا أَنَا ‏ ‏بِالْغُمَيْصَاءِ بِنْتِ مِلْحَانَ ‏","","",""],[11595,11595,"","আমরা বাবার ছেলেকে বলেছিলাম ঘোড়ার বদলে ঘোড়া নিয়ে যেতে। যারা বলেছে, ঈশ্বর মাথা নিচু করে আত্মসমর্পণ করেছেন এবং আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ قَالُوا وَكَيْفَ يَسْتَعْمِلُهُ قَالَ يُوَفِّقُهُ لِعَمَلٍ صَالِحٍ قَبْلَ مَوْتِهِ ‏","","",""],[11596,11596,"","আমরা বাবার ছেলেকে একটা ঘোড়ার কথা বলেছি, যারা বলেছে যে খোদা তাদের স্বপ্ন দেখে যেতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[11597,11597,"","আমরা বাবার ছেলের সাথে কথা বলেছি... ...যে মানুষ ঈশ্বরের সাথে শান্তিতে আছে, তার সাথে শান্তি আছে। আমার ছেলে বলেছিল, আল্লাহ আমাদের সাথে হাঁটতে হবে। আমরা বলছি, আল্লাহ আমাদের জন্য ঈশ্বরের দোহাই নিয়ে এসেছি। আমরা এখন আমাদের জীবনের জন্য। আমরা একটি নতুন জিনিস বেছে নিয়েছি। আমরা জানি, আমরা কি করতে পারি? তার সাথে যেতে যেতে, আমি বাবার ছেলের সাথে দেখা করেছি, তার উপর আস্থা রেখে যে কিনা তার নিজের ছেলের উপর বসে আছে। যেমন বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ قَالَ مَا هَذَا قَالُوا نَذَرَ أَنْ يَمْشِيَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَغَنِيٌّ أَنْ يُعَذِّبَ هَذَا نَفْسَهُ فَأَمَرَهُ فَرَكِبَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[11598,11598,"","আমরা বাবার ছেলেকে বলেছিলাম যে সে তার জন্য প্রার্থনা করছে, সে আল্লাহকে খুন করার চেষ্টা করছে, কিন্তু সে বলেছিল সে ছিল সে ঈশ্বরের একজন বন্দী।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَدْ ‏ ‏جَهَدَهُ الْمَشْيُ فَقَالَ ارْكَبْهَا فَقَالَ يَا رَسُولَ اللَّهِ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ‏ ‏ارْكَبْهَا وَإِنْ كَانَتْ ‏ ‏بَدَنَةً ‏","","",""],[11599,11599,"","আমরা আমার বাবার ছেলের সাথে কথা বলেছি... ...যে লোকদের জন্য হাত কেটেছিল... ...সে বলেছে যে মা মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يَسُوقُ ‏ ‏بِأُمَّهَاتِ الْمُؤْمِنِينَ يُقَالُ لَهُ ‏ ‏أَنْجَشَةُ ‏ ‏فَاشْتَدَّ فِي ‏ ‏السِّيَاقَةِ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدَكَ سَوْقًا ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[11600,11600,"","আমরা বাবার ছেলেকে বলেছিলাম একটা ঘোড়া সম্পর্কে... ...যে মানুষ তাকে খুন করতে চায়... ...তাকে উদ্ধার করতে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং যদি আপনি চান তাহলে তাকে আত্মসমর্পণ করবেন। আমাদের ছেড়ে চলে যান, যারা তার যোগ্যতা থেকে মদ পান করবে। আমি দুঃখিত, আমি বিশ্বাস করি, বা তাঁরা প্রভুর মেসারের সাথে চলে যাবে। হাত নিচে পড়ে গিয়ে তাদের কাছে উৎসর্গ করে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَسْلَمَ نَاسٌ مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ خَرَجْتُمْ إِلَى ‏ ‏ذَوْدٍ ‏ ‏لَنَا فَشَرِبْتُمْ مِنْ أَلْبَانِهَا ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَقَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَبْوَالِهَا ‏ ‏فَفَعَلُوا فَلَمَّا ‏ ‏صَحُّوا ‏ ‏كَفَرُوا بَعْدَ إِسْلَامِهِمْ وَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤْمِنًا ‏ ‏أَوْ مُسْلِمًا ‏ ‏وَسَاقُوا ‏ ‏ذَوْدَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَرَبُوا مُحَارِبِينَ فَأَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي آثَارِهِمْ فَأُخِذُوا ‏ ‏فَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ وَتَرَكَهُمْ فِي ‏ ‏الْحَرَّةِ ‏ ‏حَتَّى مَاتُوا ‏","","",""]];
